const COMP = [["Käuferrechte","Ich kann Lieferverzug und mangelhafte Lieferung unterscheiden und die passenden Käuferrechte prüfen."],["Fristen","Ich kann beim Wareneingang und bei Lieferproblemen rechtzeitig handeln und offene Schritte im Blick behalten."],["Abstimmung","Ich kann Einkauf, Wareneingang, Vertrieb und Lieferant mit sachlichen, konkreten Angaben in die Lösung einbinden."],["Belegabgleich","Ich kann Belege vergleichen, Abweichungen berechnen und eine passende Abhilfe nachvollziehbar begründen."],["Dokumentation","Ich kann Warenprüfung, Belege und zwei sachliche E-Mail-Entwürfe digital und nachvollziehbar aufbereiten."]];
const BANK = [{"id":0,"l":1,"c":0,"type":"multi","caseLabel":"LS 3.3 · Wenn Lieferungen nicht wie vereinbart erfolgen","title":"Bestellung richtig lesen","scene":"Die Einkaufsabteilung von Global Bike prüft die Bestellung über Verbandkästen. Für den Soll-Ist-Vergleich benötigt sie Artikel, Menge und Termin.","ask":"Welche Angaben nennt die Bestellung?","options":["Artikelnummer LS-2026-0842","Lieferschein vom 19.06.2026","Verbindlicher Liefertermin 15.06.2026","100 Verbandkästen","95 Verbandkästen","Artikelnummer FAID1000"],"answer":[2,3,5],"criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","why":"Bestellt sind 100 Verbandkästen des Artikels FAID1000 zum 15.06.2026. Der spätere Lieferschein und die gezählten Stücke beschreiben andere Teile des Vorgangs.","hint":"Suche die Angaben dazu, was der Lieferant liefern sollte.","steps":"Trenne die vereinbarten Angaben vom Liefertag und von der späteren Zählung.","example":"Eine Bestellmenge ist ein Soll-Wert. Eine Zählung zeigt den Ist-Wert.","sourceRefs":["Handlungssituation","Ü1","Ü2","Ü3","Ü4"]},{"id":1,"l":1,"c":3,"type":"multi","caseLabel":"LS 3.3 · Wenn Lieferungen nicht wie vereinbart erfolgen","title":"Bestellwert nachvollziehen","scene":"In der Bestellung stehen 100 Verbandkästen zu je 12,50 Euro netto. Für die Übung gilt 19 Prozent Umsatzsteuer.","ask":"Welche Ergebnisse kann Global Bike in die Berechnung übernehmen?","options":["Umsatzsteuer: 237,50 Euro","Bruttobestellwert: 1.250,00 Euro","Umsatzsteuer: 19,00 Euro","Nettobestellwert: 125,00 Euro","Bruttobestellwert: 1.487,50 Euro","Nettobestellwert: 1.250,00 Euro"],"answer":[0,4,5],"criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","why":"100 × 12,50 Euro ergeben 1.250,00 Euro netto. 19 Prozent davon sind 237,50 Euro Umsatzsteuer. Zusammen sind das 1.487,50 Euro brutto.","hint":"Berechne zuerst den Gesamtpreis ohne Umsatzsteuer.","steps":"Multipliziere Menge und Nettostückpreis. Berechne die Steuer aus dem Nettogesamtwert und addiere sie.","example":"19 Prozent ist der Steuersatz. Der Steuerbetrag wird in Euro angegeben.","sourceRefs":["Handlungssituation","Ü1","Ü2","Ü3","Ü4"]},{"id":2,"l":1,"c":4,"type":"multi","caseLabel":"LS 3.3 · Wenn Lieferungen nicht wie vereinbart erfolgen","title":"Lieferschein und Zählung unterscheiden","scene":"Im Vorgang stehen der Lieferschein und die Ergebnisse der Warenprüfung nebeneinander.","ask":"Welche Angaben übernimmt der Einkauf ausdrücklich vom Lieferschein?","options":["10 Kartons","100 Stück","15.06.2026 als Datum der Ausstellung","19.06.2026 als Datum","8 Gehäuse mit Rissen","95 Stück als geprüfter Wareneingang"],"answer":[0,1,3],"criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","why":"Der Lieferschein nennt 100 Stück in 10 Kartons und trägt das Datum 19.06.2026. Die Ist-Menge und Schäden stammen aus der Warenprüfung.","hint":"Frage bei jeder Angabe, ob der Lieferant sie vorgedruckt hat oder der Wareneingang sie festgestellt hat.","steps":"Schreibe zwei Bereiche auf: Lieferschein und Prüfung. Ordne dann die einzelnen Angaben zu.","example":"Die Zahl auf einem Lieferschein muss mit der Zählung abgeglichen werden.","sourceRefs":["Handlungssituation","Ü1","Ü2","Ü3","Ü4"]},{"id":3,"l":1,"c":4,"type":"multi","caseLabel":"LS 3.3 · Wenn Lieferungen nicht wie vereinbart erfolgen","title":"Die Ist-Menge dokumentieren","scene":"In der Bestellung und auf dem Lieferschein stehen jeweils 100 Stück. Elias zählt bei der Kontrolle 95 Stück.","ask":"Was gehört in einen nachvollziehbaren digitalen Eintrag?","options":["Fehlmenge 8 Stück","Die Menge auf dem Lieferschein stimmt mit dem Ist überein.","Der Lieferbeleg wird still auf 95 geändert.","Hinweis, dass Lieferschein und Zählung abweichen","Ist-Menge 95 Stück","Fehlmenge 5 Stück"],"answer":[3,4,5],"criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","why":"Zwischen den 100 Stück auf dem Lieferschein und der Ist-Menge von 95 Stück liegen 5 fehlende Stücke. Beide Werte müssen nachvollziehbar bleiben.","hint":"Rechne Lieferbeleg minus Zählergebnis.","steps":"Halte Beleg- und Ist-Wert getrennt fest. Gib die Differenz als Fehlmenge an.","example":"Ein dokumentierter Ist-Wert ändert die ursprüngliche Lieferangabe nicht.","sourceRefs":["Handlungssituation","Ü1","Ü2","Ü3","Ü4"]},{"id":4,"l":1,"c":2,"type":"multi","caseLabel":"LS 3.3 · Wenn Lieferungen nicht wie vereinbart erfolgen","title":"Beschaffenheit erfassen","scene":"Elias prüft die Kartons und Verbandkästen. Einkauf und Vertrieb sollen mit konkreten Angaben weiterarbeiten.","ask":"Welche Beobachtungen aus dem Wareneingang gibt Elias weiter?","options":["Die falsche Ware ist eingetroffen.","Die Gehäuse sind unbeschädigt.","2 Kartons haben Druckstellen.","Bei 8 Gehäusen sind Risse sichtbar.","Alle 95 Gehäuse sind beschädigt.","Alle Inhalte der gelieferten Verbandkästen sind vollständig."],"answer":[2,3,5],"criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","why":"Zwei eingedrückte Kartons und acht gerissene Gehäuse sind dokumentiert. Die Inhalte der gelieferten Verbandkästen sind vollständig.","hint":"Unterscheide Gehäuse, Inhalt und Verpackung.","steps":"Ordne jede Zahl ihrem Gegenstand zu. Gib dem Team beobachtete Schäden und intakte Merkmale getrennt weiter.","example":"Vollständiger Inhalt und beschädigtes Gehäuse können zugleich vorliegen.","sourceRefs":["Handlungssituation","Ü1","Ü2","Ü3","Ü4"]},{"id":5,"l":1,"c":3,"type":"multi","caseLabel":"LS 3.3 · Wenn Lieferungen nicht wie vereinbart erfolgen","title":"Verfügbare Stückzahl ermitteln","scene":"95 Verbandkästen sind eingetroffen. 8 davon haben sichtbare Risse. Bestellt waren 100 Stück.","ask":"Welche Werte passen in den Soll-Ist-Vergleich?","options":["87 Stück ohne sichtbare Schäden","95 Stück ohne sichtbare Schäden","8 bestellte Stücke fehlen.","13 Stück fehlen oder sind beschädigt.","92 Stück ohne sichtbare Schäden","5 bestellte Stücke fehlen."],"answer":[0,3,5],"criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","why":"95 − 8 ergeben 87 Stück ohne sichtbare Schäden. 100 − 95 ergeben 5 fehlende Stücke. 5 fehlende und 8 beschädigte Stücke ergeben zusammen 13 betroffene Stücke.","hint":"Starte für die sichtbaren Schäden bei den tatsächlich angekommenen Stückzahlen.","steps":"Rechne zuerst bestellte minus erhaltene Stücke und dann erhaltene minus beschädigte Stücke.","example":"Fehlende Ware und beschädigte Ware sind zwei unterschiedliche Teilmengen.","sourceRefs":["Handlungssituation","Ü1","Ü2","Ü3","Ü4"]},{"id":6,"l":1,"c":1,"type":"multi","caseLabel":"LS 3.3 · Wenn Lieferungen nicht wie vereinbart erfolgen","title":"Die Lieferdaten festhalten","scene":"Für den Einkauf soll die Wareneingangsprüfung Liefertermin und tatsächlichen Eingang auf einer Zeitachse zeigen.","ask":"Welche Einträge sind richtig?","options":["Lieferung mit fünf Kalendertagen Verspätung","Lieferung mit vier Kalendertagen Verspätung","Eingang am 19.06.2026","Eingang am 16.06.2026","Vereinbarter Liefertermin am 15.06.2026","Eingang am 15.06.2026"],"answer":[1,2,4],"criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","why":"Die vereinbarte Lieferung zum 15.06. kam tatsächlich am 19.06. an. Der Abstand beträgt vier Kalendertage.","hint":"Vergleiche die beiden Datumsangaben als Soll und Ist.","steps":"Markiere zuerst den Termin und danach den Wareneingang. Zähle die Tage nach dem 15.06. bis zum 19.06.","example":"Am 16.06. war seit dem Liefertermin ein Kalendertag vergangen.","sourceRefs":["Handlungssituation","Ü1","Ü2","Ü3","Ü4"]},{"id":7,"l":1,"c":2,"type":"multi","caseLabel":"LS 3.3 · Wenn Lieferungen nicht wie vereinbart erfolgen","title":"Abweichungen für den Einkauf sichern","scene":"Der Wareneingang meldet beschädigte Verbandkästen und eine Fehlmenge. Der Einkauf muss die Lieferung eindeutig zuordnen und die Abweichung nachvollziehen können.","ask":"Welche Informationen helfen der zuständigen Person?","options":["Bestell- und Lieferscheinnummer","Nur die gesamte Bestellmenge ohne Befund","Fehlende und beschädigte Mengen","Fotos der Schäden","Ohne Prüfung geschätzte Kosten","Datum der Warenprüfung"],"answer":[0,2,3,5],"criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","why":"Belegnummern ordnen die Lieferung zu. Prüfdatum, tatsächliche Mengen und Fotos belegen den Zustand bei der Kontrolle.","hint":"Denke an die Angaben zum Beleg und an die Beweise zur Abweichung.","steps":"Liste Belegbezug, Datum, Mengen und Fotos auf. Vergleiche jede Option mit dieser Liste.","example":"Mit Foto und Mengenangabe kann der Einkauf bei Rückfragen zeigen, welche Schäden festgestellt wurden.","sourceRefs":["Handlungssituation","Ü1","Ü2","Ü3","Ü4"]},{"id":8,"l":1,"c":1,"type":"multi","caseLabel":"LS 3.3 · Wenn Lieferungen nicht wie vereinbart erfolgen","title":"Beschädigte Ware getrennt behandeln","scene":"Elias hat die Ware geprüft. Ein Teil der Kästen weist Risse auf. Nun muss er dem Einkauf eine sichere Weiterbearbeitung ermöglichen.","ask":"Welche Maßnahmen sind sinnvoll?","options":["Die Schäden fotografieren.","Beschädigte Kästen zur Kundenlieferung freigeben.","Die Fehlmenge zunächst aus der Dokumentation streichen.","Beschädigte Ware getrennt lagern.","Den Lieferschein ohne Vermerk ändern.","Den Einkauf unverzüglich intern informieren."],"answer":[0,3,5],"criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","why":"Getrennte Lagerung verhindert Verwechslungen. Fotos und eine konkrete Meldung helfen dem Einkauf, die Abweichungen gegenüber dem Lieferanten zu bearbeiten.","hint":"Denke an zwei Ziele: Belege sichern und beschädigte Ware nicht versehentlich weitergeben.","steps":"Ordne die Optionen dem Umgang mit der Ware oder der Meldung an den Einkauf zu.","example":"Ein beschädigter Kasten bleibt separat, bis über die weitere Bearbeitung entschieden ist.","sourceRefs":["Handlungssituation","Ü1","Ü2","Ü3","Ü4"]},{"id":9,"l":1,"c":0,"type":"multi","caseLabel":"LS 3.3 · Wenn Lieferungen nicht wie vereinbart erfolgen","title":"Verspätung und Mangel unterscheiden","scene":"Die Ware kommt nach dem Liefertermin an. Bei der Prüfung findet Elias gerissene Gehäuse und zählt weniger Ware als bestellt.","ask":"Welche Zuordnungen helfen beim Prüfen der Kaufvertragsstörung?","options":["Die geringere Menge ist eine Abweichung der Lieferung.","Die zu späte Lieferung betrifft die Zeit der Leistung.","Die Verspätung allein beweist einen Schaden in Geld.","Die Risse sind eine Terminabweichung, weil die Lieferung verspätet eintraf.","Die vollständigen Inhalte beweisen, dass die Lieferung insgesamt fehlerfrei ist.","Die gerissenen Gehäuse sind eine Abweichung der Beschaffenheit."],"answer":[0,1,5],"criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","why":"Der verspätete Eingang betrifft den Liefertermin. Die Menge und die Risse werden getrennt als Abweichungen der gelieferten Ware geprüft.","hint":"Unterscheide Zeitpunkt, Menge und Zustand.","steps":"Ordne zuerst das Datum zu. Prüfe dann gesondert, was und wie viel Global Bike geliefert erhielt.","example":"Eine pünktliche Lieferung kann eine Fehlmenge haben. Eine verspätete Lieferung kann in richtiger Menge kommen.","sourceRefs":["Handlungssituation","Ü1","Ü2","Ü3","Ü4"]},{"id":10,"l":1,"c":0,"type":"multi","caseLabel":"LS 3.3 · Wenn Lieferungen nicht wie vereinbart erfolgen","title":"Mahnung und Nachfrist auseinanderhalten","scene":"Der Liefertermin ist abgelaufen. Der Einkauf überlegt, ob er zur Lieferung auffordert und eine zusätzliche Frist festlegt.","ask":"Welche Aussagen helfen, beide Schritte richtig einzuordnen?","options":["Ein festes Kalenderdatum kann eine Mahnung für den Verzug entbehrlich machen.","Nachfrist ist dasselbe wie ursprünglicher Liefertermin.","Eine Mahnung fordert zur fälligen Leistung auf.","Eine Nachfrist dient dazu, den Schaden automatisch festzusetzen.","Eine Mahnung ersetzt automatisch jede Nachfrist.","Eine Nachfrist gibt zusätzliche Zeit für die Leistung."],"answer":[0,2,5],"criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","why":"Eine Mahnung ist eine Aufforderung zur fälligen Leistung. Eine Nachfrist gibt zusätzliche Zeit. Bei einem kalendermäßig bestimmten Termin kann die Mahnung für den Verzug entbehrlich sein.","hint":"Frage, ob es um eine Aufforderung oder um einen zusätzlichen Zeitraum geht.","steps":"Ordne jedem Begriff seine Funktion zu. Prüfe dann gesondert die Bedeutung des vereinbarten Datums.","example":"„Bitte liefern Sie“ ist eine Aufforderung. „Bis zu einem angemessenen neuen Datum“ ergänzt eine Frist.","sourceRefs":["Handlungssituation","Ü1","Ü2","Ü3","Ü4"]},{"id":11,"l":1,"c":2,"type":"multi","caseLabel":"LS 3.3 · Wenn Lieferungen nicht wie vereinbart erfolgen","title":"Sachlich kommunizieren","scene":"Der Einkauf will zuverlässig mit dem Lieferanten zusammenarbeiten und die Dokumentation zum Vorgang sachlich halten.","ask":"Welche Formulierungen helfen beim Klären des Vorgangs?","options":["„Die Bearbeiterin ist persönlich für alle künftigen Ausfälle verantwortlich.“","„Bitte teilen Sie uns den Liefertermin mit.“","„Antworten Sie erst, wenn Sie alle unsere Kunden entschädigt haben.“","„Bei der Prüfung stellten wir folgende Abweichungen fest.“","„Wir tragen vorsorglich eine zusätzliche Schadenssumme ein.“","„Wir bitten um kurzfristige Rückmeldung.“"],"answer":[1,3,5],"criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","why":"Eine sachliche Nachricht nennt Beobachtungen, bittet um einen Termin oder fordert eine Rückmeldung an. Unbelegte Ansprüche und persönliche Vorwürfe erschweren die Klärung.","hint":"Kreise die Formulierungen ein, die eine konkrete Information oder Handlung benennen.","steps":"Prüfe, ob der Satz überprüfbare Angaben enthält und der Lieferant sinnvoll reagieren kann.","example":"„Bitte bestätigen Sie den Termin“ zeigt klar, was von der anderen Seite erwartet wird.","sourceRefs":["Handlungssituation","Ü1","Ü2","Ü3","Ü4"]},{"id":12,"l":2,"c":0,"type":"multi","caseLabel":"LS 3.3 · Wenn Lieferungen nicht wie vereinbart erfolgen","title":"Fälligkeit am 16.06. prüfen","scene":"Der bestätigte Liefertermin war der 15.06.2026. Am 16.06. hat Global Bike noch keine Ware erhalten.","ask":"Welche Aussagen sind für den Prüfstand am 16.06. richtig?","options":["Die Lieferung ist fällig und blieb aus.","Die Lieferpflicht wird erst am 19.06. fällig.","Die Ursache ist durch die Nachricht vom 17.06. bereits belegt.","Der vereinbarte Termin liegt einen Tag zurück.","Die Mahnung ist wegen des bestimmten Datums für den Verzug grundsätzlich entbehrlich.","Die Vereinbarung ist durch die Verspätung automatisch aufgehoben."],"answer":[0,3,4],"criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","why":"Am 16.06. steht die fällige Lieferung aus. Für den Verzug ist eine Mahnung wegen des vereinbarten Datums grundsätzlich entbehrlich. Die Ursache ist zu diesem Zeitpunkt noch offen.","hint":"Vergleiche nur die bis zum 16.06. bekannten Fakten mit den ersten Schritten der Verzugsprüfung.","steps":"Notiere vereinbarten Termin, Lieferstatus und die Bedeutung des Kalenderdatums. Kennzeichne offene Angaben gesondert.","example":"Eine Nachricht vom 17.06. gehört nicht in eine Feststellung aus Sicht des 16.06.","sourceRefs":["Handlungssituation","Ü1","Ü2","Ü3","Ü4"]},{"id":13,"l":2,"c":0,"type":"multi","caseLabel":"LS 3.3 · Wenn Lieferungen nicht wie vereinbart erfolgen","title":"Die Nachricht vom 17.06. auswerten","scene":"Am 17.06. nennt der Lieferant einen internen Bearbeitungsfehler. Global Bike prüft nun, welche Bedeutung die neue Information hat.","ask":"Was folgt aus der Nachricht?","options":["Sie war bereits am 16.06. verfügbar.","Sie belegt die Ankunft der Ware am 17.06.","Die Ursache kann jetzt nachvollziehbar in der Prüfung dokumentiert werden.","Sie nennt einen Fehler des Lieferanten.","Der Fehler spricht dafür, dass der Lieferant die Verspätung zu vertreten hat.","Sie beweist eine bestimmte Höhe des Schadens."],"answer":[2,3,4],"criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","why":"Der interne Bearbeitungsfehler ist ein Hinweis auf das Vertretenmüssen. Die Nachricht ist erst ab dem 17.06. verfügbar und belegt keine Schadenshöhe.","hint":"Prüfe, wozu die neue Information tatsächlich etwas aussagt.","steps":"Ordne die Nachricht nach Datum ein. Entscheide getrennt über Ursache, Ankunft und Schadenshöhe.","example":"Eine Erklärung zur Ursache beweist noch keine entstandenen Mehrkosten.","sourceRefs":["Handlungssituation","Ü1","Ü2","Ü3","Ü4"]},{"id":14,"l":2,"c":1,"type":"multi","caseLabel":"LS 3.3 · Wenn Lieferungen nicht wie vereinbart erfolgen","title":"Am 16.06. reagieren","scene":"Das Team überprüft den Kalender und die Wareneingangsmeldungen. Der 15.06. ist vorbei und die Ware fehlt. Für die Kunden wird sie noch benötigt.","ask":"Welche Schritte passen zu diesem Stand?","options":["Den Vertrag sofort als erledigt ablegen.","Lieferung verlangen.","Den aktuellen Lieferstatus anfragen.","Eine Mängelrüge über acht gerissene Gehäuse verschicken.","Eine noch unbekannte Pauschale als Schadenssumme in Rechnung stellen.","Bei Bedarf einen angemessenen zusätzlichen Liefertermin setzen."],"answer":[1,2,5],"criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","why":"Global Bike kann die fällige Lieferung verlangen und nach dem Lieferstatus fragen. Eine angemessene Nachfrist kann weitere Schritte vorbereiten. Mängel und konkrete Kosten sind am 16.06. noch nicht festgestellt.","hint":"Was braucht das Team für die Weiterarbeit und was ist an diesem Tag bereits bekannt?","steps":"Trenne akute Lieferanfrage, mögliche Frist und später feststellbare Abweichungen.","example":"Eine Sachstandsanfrage kann zugleich eine klare Aufforderung zur Lieferung enthalten.","sourceRefs":["Handlungssituation","Ü1","Ü2","Ü3","Ü4"]},{"id":15,"l":2,"c":3,"type":"multi","caseLabel":"LS 3.3 · Wenn Lieferungen nicht wie vereinbart erfolgen","title":"Eine Geldforderung prüfen","scene":"Die Verspätung belastet die Kundenversorgung. Bis zum 19.06. sind keine konkreten Mehrkosten bekannt. Jan möchte wissen, was Global Bike bereits belegen kann.","ask":"Welche Einträge sind für die Prüfung eines Verzugsschadens tragfähig?","options":["Ein Anspruch wegen Verzögerung setzt Verzug voraus.","Weitere Kosten zunächst als ungeklärt festhalten.","Ein möglicher Schaden muss mit konkreten Angaben belegt werden können.","Vier verspätete Tage belegen bereits eine bestimmte Geldsumme.","Alle wartenden Kunden haben sicher storniert.","Bei einer Verspätung sind stets 500 Euro fällig."],"answer":[0,1,2],"criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","why":"Ein Verzugsschaden setzt Verzug und einen nachvollziehbaren Schaden voraus. Bis zum 19.06. ist keine konkrete Summe belegt.","hint":"Trenne ein betriebliches Risiko von einem nachweisbaren Geldbetrag.","steps":"Sammle zuerst Voraussetzungen und vorhandene Belege. Kennzeichne nicht belegte Positionen als offen.","example":"Wartende Kunden zeigen möglichen Handlungsbedarf. Ein bestimmter Umsatzverlust ist damit noch nicht belegt.","sourceRefs":["Handlungssituation","Ü1","Ü2","Ü3","Ü4"]},{"id":16,"l":2,"c":0,"type":"multi","caseLabel":"LS 3.3 · Wenn Lieferungen nicht wie vereinbart erfolgen","title":"Bei ausbleibender Lieferung den Rücktritt prüfen","scene":"Übungsvariante: Global Bike erwägt einen Rücktritt, weil fällige Ware weiterhin aussteht. Der Einkauf hat bisher keine Nachfrist gesetzt.","ask":"Welche Prüfschritte oder Folgerungen passen?","options":["Grundsätzlich eine angemessene zusätzliche Frist zur Lieferung setzen.","Der Vertrag endet mit der Verspätung automatisch.","Vor einem Rücktritt prüfen, ob eine erforderliche Nachfrist erfolglos abgelaufen ist.","Verschulden immer als zwingende Rücktrittsvoraussetzung behandeln.","Eine Ausnahme von der Fristsetzung nur bei erfüllten gesetzlichen Voraussetzungen annehmen.","Eine Mahnung und ein Rücktritt lösen dieselbe Wirkung aus."],"answer":[0,2,4],"criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","why":"Im Regelfall muss eine angemessene Nachfrist erfolglos ablaufen. Gesetzliche Ausnahmen sind möglich. Aus der Verspätung allein folgt kein automatischer Rücktritt.","hint":"Unterscheide das ursprüngliche Kalenderdatum von einer zusätzlichen Frist vor einem möglichen Rücktritt.","steps":"Ordne den Ablauf nach Fälligkeit, Nachfrist und Prüfung weiterer Rechte.","example":"Eine verstrichene Lieferfrist und eine erfolglos abgelaufene Nachfrist sind zwei verschiedene Befunde.","sourceRefs":["Handlungssituation","Ü1","Ü2","Ü3","Ü4"]},{"id":17,"l":2,"c":1,"type":"multi","caseLabel":"LS 3.3 · Wenn Lieferungen nicht wie vereinbart erfolgen","title":"Am 19.06. unverzüglich rügen","scene":"Elias hat alle Kartons geöffnet und den Befund an den Einkauf gegeben. Die Lieferabweichung ist erkannt.","ask":"Welche Maßnahmen sollte die einkaufende Person jetzt anstoßen?","options":["Die Fehlmenge konkret nennen.","Die acht gerissenen Gehäuse konkret beschreiben.","Nur den überzogenen Liefertermin nennen.","Die sichtbaren Schäden erst beim nächsten Monatsgespräch erwähnen.","Den Lieferanten unverzüglich über die Abweichungen informieren.","Bei der internen Meldung bleiben und auf eine Anfrage des Lieferanten warten."],"answer":[0,1,4],"criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","why":"Die Einkaufsmeldung ersetzt die Anzeige an den Lieferanten nicht. Die Rüge nennt zeitnah konkret die Fehlmenge und die sichtbaren Schäden.","hint":"Überlege, wer die Abweichungen jetzt kennen muss und was diese Person zur Prüfung braucht.","steps":"Übertrage die Werte aus dem Wareneingang in eine Nachricht an den Lieferanten.","example":"„Fünf Stück fehlen und acht Gehäuse sind gerissen“ ist konkreter als „Die Ware war schlecht“.","sourceRefs":["Handlungssituation","Ü1","Ü2","Ü3","Ü4"]},{"id":18,"l":2,"c":3,"type":"multi","caseLabel":"LS 3.3 · Wenn Lieferungen nicht wie vereinbart erfolgen","title":"Fehlmenge und Nacherfüllung berechnen","scene":"Global Bike hat 100 Stück bestellt. Eingetroffen sind 95. Acht der eingetroffenen Kästen haben Risse. Global Bike will am Ende 100 vertragsgemäße Stück erhalten.","ask":"Welche Forderungen bilden diesen Bedarf sachlich ab?","options":["Weitere 100 Stück verlangen und alle 95 gelieferten behalten.","Die 8 beschädigten Kästen und 5 fehlenden Stücke als getrennte Positionen aufführen.","5 fehlende Stücke nachliefern lassen.","Alle 13 betroffenen Stücke als vollständige Fehlmenge bezeichnen.","8 mangelfreie Stücke als Ersatz für die beschädigten Kästen verlangen.","8 fehlende Stücke und 5 beschädigte Stücke angeben."],"answer":[1,2,4],"criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","why":"Von den 95 gelieferten Stücken sind 8 beschädigt. 5 Stück sind gar nicht angekommen. Ersatz für 8 und Nachlieferung von 5 decken beide Abweichungen getrennt ab.","hint":"Was ist angekommen, aber beschädigt, und was ist gar nicht angekommen?","steps":"Berechne zuerst 100 minus 95. Nenne die acht beschädigten Stücke getrennt und wähle die dazu passende Abhilfe.","example":"Ersatz tauscht fehlerhafte Ware aus. Nachlieferung füllt eine Lücke in der Menge.","sourceRefs":["Handlungssituation","Ü1","Ü2","Ü3","Ü4"]},{"id":19,"l":2,"c":2,"type":"multi","caseLabel":"LS 3.3 · Wenn Lieferungen nicht wie vereinbart erfolgen","title":"Reparatur oder Ersatz abwägen","scene":"Übungsvariante: Der Lieferant bietet für beschädigte Ware eine Reparatur oder eine Ersatzlieferung an. Jan wartet auf Ware für Kunden.","ask":"Welche Fragen helfen bei der Abstimmung mit Einkauf und Vertrieb?","options":["Erfüllen die reparierten Stücke anschließend die Anforderungen?","Welche Farbe hat die E-Mail des Lieferanten?","Welche Lieferzeit passt zum Kundenbedarf?","Muss Global Bike bei Ersatz immer den Kaufpreis doppelt bezahlen?","Wie schnell wäre bei jeder Lösung wieder mangelfreie Ware verfügbar?","Ist die zeitlich früheste Lösung grundsätzlich auch ohne Prüfung der Qualität die richtige?"],"answer":[0,2,4],"criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","why":"Für die Kundenversorgung zählen Dauer und Qualität der Abhilfe. Einkauf und Vertrieb können die Optionen anhand von Verfügbarkeit und Kundenbedarf gemeinsam einschätzen.","hint":"Frage nach Qualität nach der Abhilfe und nach dem Zeitpunkt, an dem sie nutzbar ist.","steps":"Vergleiche für beide Möglichkeiten die versprochene Dauer und das Ergebnis für die Kundschaft.","example":"Eine schnelle Reparatur hilft nur, wenn die Ware danach vertragsgemäß ist.","sourceRefs":["Handlungssituation","Ü1","Ü2","Ü3","Ü4"]},{"id":20,"l":2,"c":2,"type":"multi","caseLabel":"LS 3.3 · Wenn Lieferungen nicht wie vereinbart erfolgen","title":"Kundenbedarf mitdenken","scene":"Der Einkauf kennt die Fehlmenge und die Beschädigungen. Der Vertrieb warnt, dass Kunden ohne ausreichende Ware warten müssen.","ask":"Welche Punkte gehören in eine gemeinsame wirtschaftliche Entscheidung?","options":["Den verzögerten Liefertermin nachträglich aus der Dokumentation löschen.","Alle wartenden Kunden pauschal als abgesprungen zählen.","Bei einem kleinen Mangel immer sofort den ganzen Vertrag auflösen.","Überprüfbare Kosten der möglichen Abhilfe berücksichtigen.","Erfragen, wann die übrige mangelfreie Ware bereitsteht.","Klären, wie viel Ware nach Sichtprüfung schon zur Verfügung steht."],"answer":[3,4,5],"criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","why":"Verfügbare einwandfreie Ware, Wartezeit und Kosten helfen bei der gemeinsamen Entscheidung. Vermutete Stornierungen sind als Risiko zu betrachten, solange sie nicht belegt sind.","hint":"Überlege, was dem Vertrieb heute und bei der nächsten Lieferung hilft.","steps":"Verbinde vorhandene Menge, erwartete Abhilfe und Kosten mit dem Bedarf der Kundschaft.","example":"Ein Teil der Kunden kann bereits versorgt werden, wenn geeignete Ware verfügbar ist.","sourceRefs":["Handlungssituation","Ü1","Ü2","Ü3","Ü4"]},{"id":21,"l":2,"c":0,"type":"multi","caseLabel":"LS 3.3 · Wenn Lieferungen nicht wie vereinbart erfolgen","title":"Weitere Rechte nach der Abhilfe abgrenzen","scene":"Übungsvariante: Eine Nacherfüllung ist trotz gesetzter angemessener Frist erfolglos geblieben. Die einkaufende Person prüft, welche weiteren Rechte in Betracht kommen.","ask":"Welche Aussagen eignen sich für die anschließende Prüfung?","options":["Eine Minderung erhöht den Preis, weil erneut geprüft wurde.","Bei erfolgloser Nacherfüllung darf man jedes Recht ohne weitere Voraussetzungen wählen.","Ein Rücktritt ist bei einem unerheblichen Mangel grundsätzlich ausgeschlossen.","Eine erfolglose Nacherfüllung kann Anlass sein, weitere Rechte zu prüfen.","Eine Reparatur ist dasselbe wie ein Rücktritt.","Bei einer Minderung bleibt der Kaufvertrag bestehen."],"answer":[2,3,5],"criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","why":"Weitere Rechte werden nach ihren jeweiligen Voraussetzungen geprüft. Eine Minderung reduziert den Preis bei fortbestehendem Vertrag. Bei einem unerheblichen Mangel ist ein Rücktritt grundsätzlich ausgeschlossen.","hint":"Welche Wirkung hat Minderung und welche Voraussetzung verdient beim Rücktritt besondere Beachtung?","steps":"Ordne die Rechte nach ihrer Wirkung. Prüfe danach, was für das gewünschte Recht erfüllt sein muss.","example":"Wer eine Preisreduzierung nutzt, wickelt dadurch nicht automatisch den Vertrag rückwärts ab.","sourceRefs":["Handlungssituation","Ü1","Ü2","Ü3","Ü4"]},{"id":22,"l":2,"c":4,"type":"multi","caseLabel":"LS 3.3 · Wenn Lieferungen nicht wie vereinbart erfolgen","title":"E-Mail aus Sicht des 16.06. prüfen","scene":"Im digitalen Entwurf zur fehlenden Lieferung steht schon die Lieferscheinnummer vom 19.06. Das Team soll die Nachricht für den 16.06. verfassen.","ask":"Was gehört in die an diesem Tag nutzbare Fassung?","options":["Die Lieferscheinnummer vom 19.06. als Beleg für den heutigen Eingang stehen lassen.","Die Risse aus der späteren Warenprüfung melden.","Den 15.06. als vereinbarten, bereits überschrittenen Liefertermin nennen.","Den erst am 17.06. genannten internen Fehler als bekannt darstellen.","Lieferung oder eine kurzfristige Terminbestätigung verlangen.","Auf die bestätigte Bestellung Bezug nehmen."],"answer":[2,4,5],"criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","why":"Die E-Mail vom 16.06. kann die Bestellung, den überschrittenen Termin und die ausstehende Lieferung nennen. Spätere Belege und Schäden gehören erst in die spätere Nachricht.","hint":"Ordne jedes Detail dem Tag zu, an dem es bekannt wurde.","steps":"Streiche aus dem Entwurf alles, was erst nach dem 16.06. feststand. Formuliere eine konkrete Bitte.","example":"Eine Nachricht kann sachlich und dringlich sein, ohne unbekannte Gründe für die fehlende Ware zu behaupten.","sourceRefs":["Handlungssituation","Ü1","Ü2","Ü3","Ü4"]},{"id":23,"l":2,"c":4,"type":"multi","caseLabel":"LS 3.3 · Wenn Lieferungen nicht wie vereinbart erfolgen","title":"Das Lernpaket vor Abgabe kontrollieren","scene":"Die Arbeit ist als Präsentation oder Mappe vorbereitet. Wareneingang, rechtliche Prüfung und zwei geschäftliche Nachrichten sollen darin überprüfbar sein.","ask":"Welche Prüfungen sind vor der digitalen Abgabe sinnvoll?","options":["Begründungen streichen, wenn die Präsentation sonst länger wird.","Nur das Titelbild und die Anzahl der Seiten prüfen.","Die beiden E-Mails tatsächlich versenden, um die Abgabe zu testen.","Prüfen, ob die geforderten Rechte und Maßnahmen begründet sind.","Prüfen, ob beide E-Mail-Entwürfe für ihren jeweiligen Zeitpunkt sachlich und vollständig sind.","Zahlen mit Bestell- und Lieferunterlagen abgleichen."],"answer":[3,4,5],"criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","why":"Jedes Format braucht vollständige, verständliche Ergebnisse: Zahlen mit Belegen, rechtlich und wirtschaftlich begründete Maßnahmen und zwei sachliche E-Mails. Diese Nachrichten bleiben Entwürfe.","hint":"Prüfe den Inhalt in allen Formaten mit denselben Kriterien.","steps":"Gleiche Zahlen und Voraussetzungen mit deinen Unterlagen ab. Öffne zuletzt beide E-Mails und prüfe Datum und Lesbarkeit.","example":"Eine schön gestaltete Präsentation ersetzt keine nachvollziehbare Mengenberechnung.","sourceRefs":["Handlungssituation","Ü1","Ü2","Ü3","Ü4"]},{"c":1,"title":"Den 16.06. vorbereiten","scene":"Am 16.06. fehlt die Lieferung der bestellten Verbandkästen. Vertraglich war der 15.06.2026 vorgesehen. Der Einkauf braucht einen ersten nachvollziehbaren Schritt.","ask":"Wie beginnst du, solange die Ursache und das tatsächliche Anlieferdatum noch offen sind?","options":["Du legst die bestätigte Bestellung und die Eingangsmeldung nebeneinander und hältst fest, welche Tatsachen jetzt belegt sind.","Du fragst den Vertrieb nach dem Bedarf und nimmst mit dem Lieferanten Kontakt zum Lieferstatus auf.","Du legst Zuständigkeiten für Lieferanfrage, Terminüberwachung und Rückmeldung an den Vertrieb fest.","Du erstellst eine Zeitleiste mit dem vereinbarten Termin und kennzeichnest den fehlenden Eingang und die noch offene Ursache getrennt.","Du klärst mit dem Wareneingang, ob die Ware tatsächlich fehlt, und vereinbarst eine kurze Abstimmung mit dem Vertrieb.","Du planst die sachliche Lieferanfrage mit Bestellbezug und bestimmst, wann der Status erneut geprüft wird."],"consequences":["Der erste Prüfstand lässt sich aus zwei zugeordneten Belegen nachvollziehen.","Du kennst den Kundenbedarf und kannst ihn bei einer belegbaren Terminrückmeldung berücksichtigen.","Die Beteiligten wissen, wer den Status prüft und wann Informationen weitergegeben werden.","Die Zeitleiste verhindert, dass spätere Erkenntnisse versehentlich als schon bekannt gelten.","Wareneingang und Vertrieb arbeiten mit demselben bestätigten Lieferstand.","Für die Erstmeldung liegen Bezug und ein konkreter Folgetermin fest."],"id":24,"l":3,"type":"story","caseLabel":"LS 3.3 · Wenn Lieferungen nicht wie vereinbart erfolgen","storyIndex":0,"logicMap":[0,1,2,0,1,2],"logicRoles":["Belegweg","Beteiligungsweg","Rahmenweg","Belegweg","Beteiligungsweg","Rahmenweg"],"sourceRefs":["Handlungssituation","Ü1","Ü2","Ü3","Ü4"],"criteria":"Wähle eine Handlung. Am Ende siehst du, wie deine sechs Entscheidungen zusammenpassen.","hint":"Welche Überlegung aus dem letzten Schritt hilft dir hier weiter?","steps":"Entscheide, welchen Beleg, welche Rückmeldung oder welche Vorgabe du jetzt prüfst.","example":"Greife eine Information aus deiner vorigen Entscheidung auf und verwende sie hier.","why":"Am Ende erhältst du eine Rückmeldung zu deiner Entscheidungskette."},{"c":0,"title":"Das Vertretenmüssen weiter prüfen","scene":"Am 17.06. meldet der Lieferant einen internen Bearbeitungsfehler. Der Einkauf wertet die Mitteilung aus. Konkrete Mehrkosten sind bis zum 19.06. nicht bekannt.","ask":"Wie arbeitest du mit der neuen Information weiter?","options":["Du hältst die Mitteilung mit Datum fest und prüfst, was sie zum Vertretenmüssen belegt.","Du klärst mit dem Lieferanten, wann die Ware nun kommt, und lässt den Vertrieb die Kundenplanung abstimmen.","Du aktualisierst den Terminplan und reservierst eine kurze Lageprüfung, bevor über weitere Schritte entschieden wird.","Du ergänzt in der Prüfung eine Zeile zur Ursache und lässt die Schadenshöhe bis zum Nachweis offen.","Du besprichst mit Einkauf und Vertrieb getrennt, was man dem Lieferanten sagen und was man Kunden verlässlich zusagen kann.","Du kontrollierst den Zeitpunkt für eine nächste Freigabe und legst fest, wer eventuelle belegte Mehrkosten erfasst."],"consequences":["Die Verantwortung kann anhand einer datierten Lieferantenmitteilung geprüft werden.","Die neue Auskunft fließt in eine abgestimmte Planung ein, ohne eine Anhörung mit einem Schadensnachweis zu verwechseln.","Es gibt einen neuen Handlungszeitpunkt, an dem die Lage anhand bekannter Informationen bewertet wird.","Ursache und Schaden bleiben getrennte Prüfpunkte.","Die Beteiligten geben nur solche Zusagen weiter, die der aktuelle Stand trägt.","Für offene Kosten ist eine spätere Belegprüfung mit Zuständigkeit vereinbart."],"id":25,"l":3,"type":"story","caseLabel":"LS 3.3 · Wenn Lieferungen nicht wie vereinbart erfolgen","storyIndex":1,"logicMap":[0,1,2,0,1,2],"logicRoles":["Belegweg","Beteiligungsweg","Rahmenweg","Belegweg","Beteiligungsweg","Rahmenweg"],"sourceRefs":["Handlungssituation","Ü1","Ü2","Ü3","Ü4"],"criteria":"Wähle eine Handlung. Am Ende siehst du, wie deine sechs Entscheidungen zusammenpassen.","hint":"Welche Überlegung aus dem letzten Schritt hilft dir hier weiter?","steps":"Entscheide, welchen Beleg, welche Rückmeldung oder welche Vorgabe du jetzt prüfst.","example":"Greife eine Information aus deiner vorigen Entscheidung auf und verwende sie hier.","why":"Am Ende erhältst du eine Rückmeldung zu deiner Entscheidungskette.","branchFrom":24,"branchText":["Beziehe die Angaben ein, die du gerade geprüft hast.","Berücksichtige die Rückmeldung oder Sichtweise, die du aufgenommen hast.","Prüfe, welche Vorgabe oder Grenze aus der vorigen Entscheidung jetzt wichtig ist.","Beziehe die Angaben ein, die du gerade geprüft hast.","Berücksichtige die Rückmeldung oder Sichtweise, die du aufgenommen hast.","Prüfe, welche Vorgabe oder Grenze aus der vorigen Entscheidung jetzt wichtig ist."]},{"c":3,"title":"Den Wareneingang bewerten","scene":"Am 19.06. treffen 95 statt 100 Verbandkästen ein. Acht der gelieferten Kästen haben Risse. Die Inhalte sind vollständig. Elias hat alle Kartons geöffnet.","ask":"Wie bringst du Mengen und Zustand in eine nachvollziehbare Arbeitsgrundlage?","options":["Du vergleichst 100 laut Bestellung und Lieferschein mit 95 gezählten Stück und stellst die acht Gehäuse mit Rissen daneben.","Du gehst die Zählung und die Fotos mit Elias durch und meldest dem Vertrieb den Stand zur verfügbaren Ware getrennt.","Du legst fest, wer die beschädigte Ware getrennt hält und wer Prüfung, Fotos und Wareneingangsmeldung abschließt.","Du rechnest 95 − 8 = 87 ohne sichtbare Schäden und dokumentierst die fünf fehlenden Stücke getrennt.","Du lässt Einkauf und Wareneingang gegenseitig prüfen, ob Fehlmenge, Schaden und Menge ohne sichtbare Schäden gleich verstanden sind.","Du stellst sicher, dass die Prüfunterlagen mit Belegbezug abgelegt werden und bis zur Lieferantenmeldung bearbeitbar bleiben."],"consequences":["Bestellmenge, Belegmenge, tatsächliche Menge und beschädigte Ware lassen sich nachvollziehen.","Der Vertrieb erhält einen verlässlichen Zwischenstand aus der Warenprüfung.","Trennung und Dokumentation sind organisiert, bevor Ware weitergegeben wird.","Die drei Teilmengen sind sauber getrennt und bilden eine Grundlage für den nächsten Schritt.","Einkauf und Wareneingang verwenden dieselben Begriffe und Mengen.","Die Unterlagen sind eindeutig zugeordnet und für die schnelle Meldung verfügbar."],"id":26,"l":3,"type":"story","caseLabel":"LS 3.3 · Wenn Lieferungen nicht wie vereinbart erfolgen","storyIndex":2,"logicMap":[0,1,2,0,1,2],"logicRoles":["Belegweg","Beteiligungsweg","Rahmenweg","Belegweg","Beteiligungsweg","Rahmenweg"],"sourceRefs":["Handlungssituation","Ü1","Ü2","Ü3","Ü4"],"criteria":"Wähle eine Handlung. Am Ende siehst du, wie deine sechs Entscheidungen zusammenpassen.","hint":"Welche Überlegung aus dem letzten Schritt hilft dir hier weiter?","steps":"Entscheide, welchen Beleg, welche Rückmeldung oder welche Vorgabe du jetzt prüfst.","example":"Greife eine Information aus deiner vorigen Entscheidung auf und verwende sie hier.","why":"Am Ende erhältst du eine Rückmeldung zu deiner Entscheidungskette.","branchFrom":25,"branchText":["Beziehe die Angaben ein, die du gerade geprüft hast.","Berücksichtige die Rückmeldung oder Sichtweise, die du aufgenommen hast.","Prüfe, welche Vorgabe oder Grenze aus der vorigen Entscheidung jetzt wichtig ist.","Beziehe die Angaben ein, die du gerade geprüft hast.","Berücksichtige die Rückmeldung oder Sichtweise, die du aufgenommen hast.","Prüfe, welche Vorgabe oder Grenze aus der vorigen Entscheidung jetzt wichtig ist."]},{"c":4,"title":"Die Lieferantenmeldung vorbereiten","scene":"Der Einkauf muss dem Lieferanten jetzt zügig mitteilen, welche Abweichungen die Warenprüfung ergeben hat.","ask":"Wie bereitest du die Mängelrüge vor?","options":["Du formulierst die Rüge mit Bestell- und Lieferscheinbezug und leitest die Fehlmenge und die beschädigte Menge aus der Zählung ab.","Du stimmst die Beschreibung kurz mit Elias ab und bittest den Lieferanten konkret um eine Rückmeldung zur Abhilfe.","Du ordnest eine Person für die unverzügliche Meldung an den Lieferanten ein und planst die Kontrolle einer Antwort.","Du legst zu den Angaben über die Risse die Fotos bereit und nennst fehlende Stücke getrennt als zweite Abweichung.","Du klärst mit dem Vertrieb, bis wann Abhilfe für Kunden benötigt wird, und bittest den Lieferanten dabei um einen realistischen Termin.","Du legst die Meldung mit Belegbezug ab und hältst fest, wer die getrennt gelagerte Ware bis zur Klärung betreut."],"consequences":["Der Lieferant kann Menge und Zustand am passenden Geschäftsvorgang prüfen.","Die Rüge enthält einen bestätigten Befund und eine klare Bitte um Rückmeldung.","Die externe Anzeige wird nicht mit der internen Weitergabe verwechselt und zeitnah umgesetzt.","Belege passen zur jeweils beschriebenen Abweichung.","Die dringliche Bitte um Abhilfe hat einen Bezug zum tatsächlichen Kundenbedarf.","Der nächste Bearbeitungsschritt bleibt für Einkauf und Wareneingang nachvollziehbar."],"id":27,"l":3,"type":"story","caseLabel":"LS 3.3 · Wenn Lieferungen nicht wie vereinbart erfolgen","storyIndex":3,"logicMap":[0,1,2,0,1,2],"logicRoles":["Belegweg","Beteiligungsweg","Rahmenweg","Belegweg","Beteiligungsweg","Rahmenweg"],"sourceRefs":["Handlungssituation","Ü1","Ü2","Ü3","Ü4"],"criteria":"Wähle eine Handlung. Am Ende siehst du, wie deine sechs Entscheidungen zusammenpassen.","hint":"Welche Überlegung aus dem letzten Schritt hilft dir hier weiter?","steps":"Entscheide, welchen Beleg, welche Rückmeldung oder welche Vorgabe du jetzt prüfst.","example":"Greife eine Information aus deiner vorigen Entscheidung auf und verwende sie hier.","why":"Am Ende erhältst du eine Rückmeldung zu deiner Entscheidungskette.","branchFrom":26,"branchText":["Beziehe die Angaben ein, die du gerade geprüft hast.","Berücksichtige die Rückmeldung oder Sichtweise, die du aufgenommen hast.","Prüfe, welche Vorgabe oder Grenze aus der vorigen Entscheidung jetzt wichtig ist.","Beziehe die Angaben ein, die du gerade geprüft hast.","Berücksichtige die Rückmeldung oder Sichtweise, die du aufgenommen hast.","Prüfe, welche Vorgabe oder Grenze aus der vorigen Entscheidung jetzt wichtig ist."]},{"c":2,"title":"Abhilfe für Kunden planen","scene":"Fünf Kästen fehlen. Acht der eingetroffenen Kästen sind beschädigt. Der Vertrieb braucht schnell einwandfreie Ware. Eine konkrete Dauer für Reparatur oder Ersatz steht noch nicht fest.","ask":"Wie bereitest du die Entscheidung über Abhilfe vor?","options":["Du bindest die Forderung nach fünf nachzuliefernden Stück und Ersatz der acht beschädigten Stück an den Prüfbeleg.","Du holst eine Auskunft zu möglichen Terminen ein und vergleichst diese mit dem Kundenbedarf des Vertriebs.","Du legst fest, wer die Antwort zur Abhilfe abfragt und wann Einkauf und Vertrieb über das weitere Vorgehen entscheiden.","Du erstellst einen Vergleich für eine mögliche Reparatur und Ersatzlieferung nach Dauer, Kosten und vertragsgemäßem Ergebnis.","Du stimmst mit Lager und Vertrieb ab, wie die 87 ohne sichtbare Schäden verfügbaren Stücke bis zur Abhilfe eingesetzt werden können.","Du planst einen Zeitpunkt zum Nachhalten der Zusage und kontrollierst, dass fehlende und beschädigte Ware als getrennte Positionen bearbeitet werden."],"consequences":["Die Forderung passt nachprüfbar zu den beiden festgestellten Abweichungen.","Die Entscheidung nutzt abgestimmte Termine und vermeidet unbelegte Lieferzusagen.","Rückmeldung und Entscheidung haben eine zuständige Person und einen klaren Zeitpunkt.","Der Einkauf kann angebotene Lösungen fachlich und wirtschaftlich vergleichen.","Der Vertrieb kann den kurzfristigen Bedarf mit der tatsächlich verfügbaren Menge abgleichen.","Die ursprünglichen Fehlerarten bleiben bis zur Abhilfe eindeutig."],"id":28,"l":3,"type":"story","caseLabel":"LS 3.3 · Wenn Lieferungen nicht wie vereinbart erfolgen","storyIndex":4,"logicMap":[0,1,2,0,1,2],"logicRoles":["Belegweg","Beteiligungsweg","Rahmenweg","Belegweg","Beteiligungsweg","Rahmenweg"],"sourceRefs":["Handlungssituation","Ü1","Ü2","Ü3","Ü4"],"criteria":"Wähle eine Handlung. Am Ende siehst du, wie deine sechs Entscheidungen zusammenpassen.","hint":"Welche Überlegung aus dem letzten Schritt hilft dir hier weiter?","steps":"Entscheide, welchen Beleg, welche Rückmeldung oder welche Vorgabe du jetzt prüfst.","example":"Greife eine Information aus deiner vorigen Entscheidung auf und verwende sie hier.","why":"Am Ende erhältst du eine Rückmeldung zu deiner Entscheidungskette.","branchFrom":27,"branchText":["Beziehe die Angaben ein, die du gerade geprüft hast.","Berücksichtige die Rückmeldung oder Sichtweise, die du aufgenommen hast.","Prüfe, welche Vorgabe oder Grenze aus der vorigen Entscheidung jetzt wichtig ist.","Beziehe die Angaben ein, die du gerade geprüft hast.","Berücksichtige die Rückmeldung oder Sichtweise, die du aufgenommen hast.","Prüfe, welche Vorgabe oder Grenze aus der vorigen Entscheidung jetzt wichtig ist."]},{"c":3,"title":"Die Empfehlung prüfen und übergeben","scene":"Das Lernpaket soll den Fall von der versäumten Lieferung bis zu den festgestellten Mängeln zeigen. Die beiden E-Mails werden als Entwürfe vorgelegt.","ask":"Wodurch machst du das Endergebnis für die Abgabe nachvollziehbar?","options":["Du prüfst alle Endzahlen mit Bestellung, Lieferschein und Zählung und belegst die gewählte Maßnahme in der Übersicht.","Du lässt eine andere Person die beiden Nachrichten aus Sicht von Lieferant und Vertrieb lesen und räumst Unklarheiten aus.","Du setzt eine Schlusskontrolle für Voraussetzungen, Abweichungen und beide E-Mails an und gibst erst die geprüfte Fassung ab.","Du trennst bei der Endprüfung belegte Abweichungen, offene Schadensbeträge und die rechtlich zu prüfenden weiteren Rechte.","Du erklärst in deiner Abgabe, wie eure Entscheidung die Kundenversorgung und die sachliche Zusammenarbeit mit dem Lieferanten berücksichtigt.","Du versiehst beide E-Mail-Entwürfe mit dem jeweils richtigen Prüfdatum und legst sie zusammen mit der Zuständigkeit für weitere Schritte ab."],"consequences":["Rechnung und Maßnahme sind anhand der ursprünglichen Belege rekonstruierbar.","Die Formulierungen werden aus verschiedenen Perspektiven überprüft und bei Bedarf verständlicher.","Vor der Abgabe sind schriftliche Prüfung, Zahlen und Nachrichten gemeinsam kontrolliert.","Der Bericht zeigt überprüfbare Feststellungen und offene Punkte getrennt.","Die Empfehlung lässt die betrieblichen Folgen und den Beitrag der Beteiligten erkennen.","Beide Nachrichten bleiben beim richtigen Kenntnisstand und lassen den nächsten Schritt erkennen."],"id":29,"l":3,"type":"story","caseLabel":"LS 3.3 · Wenn Lieferungen nicht wie vereinbart erfolgen","storyIndex":5,"logicMap":[0,1,2,0,1,2],"logicRoles":["Belegweg","Beteiligungsweg","Rahmenweg","Belegweg","Beteiligungsweg","Rahmenweg"],"sourceRefs":["Handlungssituation","Ü1","Ü2","Ü3","Ü4"],"criteria":"Wähle eine Handlung. Am Ende siehst du, wie deine sechs Entscheidungen zusammenpassen.","hint":"Welche Überlegung aus dem letzten Schritt hilft dir hier weiter?","steps":"Entscheide, welchen Beleg, welche Rückmeldung oder welche Vorgabe du jetzt prüfst.","example":"Greife eine Information aus deiner vorigen Entscheidung auf und verwende sie hier.","why":"Am Ende erhältst du eine Rückmeldung zu deiner Entscheidungskette.","branchFrom":28,"branchText":["Beziehe die Angaben ein, die du gerade geprüft hast.","Berücksichtige die Rückmeldung oder Sichtweise, die du aufgenommen hast.","Prüfe, welche Vorgabe oder Grenze aus der vorigen Entscheidung jetzt wichtig ist.","Beziehe die Angaben ein, die du gerade geprüft hast.","Berücksichtige die Rückmeldung oder Sichtweise, die du aufgenommen hast.","Prüfe, welche Vorgabe oder Grenze aus der vorigen Entscheidung jetzt wichtig ist."]},{"id":30,"l":1,"c":0,"type":"multi","caseLabel":"LS 3.3 · Wenn Lieferungen nicht wie vereinbart erfolgen","title":"Soll-Angaben markieren","scene":"Im Fall bestellt Global Bike den Artikel FAID1000. Der Auftrag nennt 100 Stück und den 15.06.2026.","ask":"Welche beiden Einträge gehören zur Frage „Was sollten wir bekommen“?","options":["Lieferung bis 15.06.2026","Bestellmenge 95 Stück","10 tatsächlich geöffnete Kartons","8 Gehäuse mit Rissen","Wareneingang am 19.06.2026","100 Stück FAID1000"],"answer":[0,5],"criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","why":"Artikel, bestellte Menge und Termin bilden das Soll vor der Lieferung.","hint":"Achte auf „sollten“. Die Zählung kommt erst später.","steps":"Halte fest, was du entscheiden oder berechnen sollst. Prüfe dann jede Aussage einzeln mit dem Hinweis.","example":"Streiche eine Aussage erst dann, wenn du zeigen kannst, welche Angabe oder Regel ihr widerspricht.","sourceRefs":["Handlungssituation","Ü1","Ü2","Ü3","Ü4"],"coreId":0,"reserveNo":1},{"id":31,"l":1,"c":0,"type":"multi","caseLabel":"LS 3.3 · Wenn Lieferungen nicht wie vereinbart erfolgen","title":"Bestellung für einen neuen Wareneingang nutzen","scene":"Übungsvariante: Ein Auftrag nennt 60 Stück FAID1000 zum 09.09. Am 10.09. meldet das Lager 58 Stück.","ask":"Was übernimmt der Einkauf in die beiden Spalten?","options":["Soll: Termin 09.09.","Soll: 60 Stück FAID1000","Ist: Liefertermin 09.09.","Soll: 58 Stück","Ist: 2 beschädigte Kästen","Ist: 58 Stück am 10.09."],"answer":[0,1,5],"criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","why":"Die Bestellung nennt 60 Stück und den Termin. Die Lagerfeststellung ist der Ist-Wert. Die Differenz beweist allein keine Beschädigung.","hint":"Ordne jede Zahl entweder dem Auftrag oder dem späteren Eingang zu.","steps":"Halte fest, was du entscheiden oder berechnen sollst. Prüfe dann jede Aussage einzeln mit dem Hinweis.","example":"Streiche eine Aussage erst dann, wenn du zeigen kannst, welche Angabe oder Regel ihr widerspricht.","sourceRefs":["Handlungssituation","Ü1","Ü2","Ü3","Ü4"],"coreId":0,"reserveNo":2},{"id":32,"l":1,"c":3,"type":"multi","caseLabel":"LS 3.3 · Wenn Lieferungen nicht wie vereinbart erfolgen","title":"Netto und brutto trennen","scene":"Für die Originalbestellung ist der Nettogesamtwert von 1.250,00 Euro schon errechnet. Der Steuerbetrag beträgt 237,50 Euro.","ask":"Was gehört in die Ergebniszeile?","options":["Netto 1.487,50 Euro","Steuersatz 237,50 Prozent","Brutto 1.487,50 Euro","Steuer 1.012,50 Euro","Brutto 237,50 Euro","Rechenweg 1.250,00 Euro plus 237,50 Euro"],"answer":[2,5],"criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","why":"Der Bruttowert enthält den Nettowert und den Steuerbetrag.","hint":"Netto plus Steuer ergibt brutto.","steps":"Halte fest, was du entscheiden oder berechnen sollst. Prüfe dann jede Aussage einzeln mit dem Hinweis.","example":"Streiche eine Aussage erst dann, wenn du zeigen kannst, welche Angabe oder Regel ihr widerspricht.","sourceRefs":["Handlungssituation","Ü1","Ü2","Ü3","Ü4"],"coreId":1,"reserveNo":1},{"id":33,"l":1,"c":3,"type":"multi","caseLabel":"LS 3.3 · Wenn Lieferungen nicht wie vereinbart erfolgen","title":"Bestellwert einer Teilmenge","scene":"Übungsvariante: Global Bike bestellt 40 Verbandkästen zu je 12,50 Euro netto. Für die Aufgabe gelten 19 Prozent Umsatzsteuer.","ask":"Welche Werte stimmen?","options":["400,00 Euro netto","595,00 Euro brutto","476,00 Euro brutto","19,00 Euro Steuer","95,00 Euro Steuer","500,00 Euro netto"],"answer":[1,4,5],"criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","why":"40 × 12,50 Euro ergeben 500,00 Euro netto. Davon sind 19 Prozent 95,00 Euro. Brutto sind es 595,00 Euro.","hint":"Berechne erst Stückzahl mal Preis. Wende 19 Prozent auf das Ergebnis an.","steps":"Halte fest, was du entscheiden oder berechnen sollst. Prüfe dann jede Aussage einzeln mit dem Hinweis.","example":"Streiche eine Aussage erst dann, wenn du zeigen kannst, welche Angabe oder Regel ihr widerspricht.","sourceRefs":["Handlungssituation","Ü1","Ü2","Ü3","Ü4"],"coreId":1,"reserveNo":2},{"id":34,"l":1,"c":4,"type":"multi","caseLabel":"LS 3.3 · Wenn Lieferungen nicht wie vereinbart erfolgen","title":"Zwei Belege vergleichen","scene":"In der Eingangsmaske stehen „Lieferant: 100 Stück“ und „Lagerzählung: 95 Stück“. Der Lieferschein stammt vom 19.06.","ask":"Welche Werte sind für den Lieferbeleg einzutragen?","options":["Menge 100 Stück","Datum des Lieferscheins 19.06.","Bestelldatum 15.06.","Menge 95 Stück","Anzahl gerissener Gehäuse: 8","Ursache: Fehlmenge von 5 Stück"],"answer":[0,1],"criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","why":"Der Lieferschein dokumentiert die Mengenangabe des Lieferanten und das Belegdatum. Die Zählung und Schäden stehen im Prüfbericht.","hint":"Frage, wer den jeweiligen Wert erfasst hat.","steps":"Halte fest, was du entscheiden oder berechnen sollst. Prüfe dann jede Aussage einzeln mit dem Hinweis.","example":"Streiche eine Aussage erst dann, wenn du zeigen kannst, welche Angabe oder Regel ihr widerspricht.","sourceRefs":["Handlungssituation","Ü1","Ü2","Ü3","Ü4"],"coreId":2,"reserveNo":1},{"id":35,"l":1,"c":4,"type":"multi","caseLabel":"LS 3.3 · Wenn Lieferungen nicht wie vereinbart erfolgen","title":"Genaue Angaben im Lieferbeleg","scene":"Übungsvariante: Der Lieferant schreibt am 10.07. „8 Kartons zu je 10 Stück“ auf den Lieferschein. Bei der Prüfung findet das Lager 78 Kästen.","ask":"Was gibt der Lieferschein an?","options":["10.07. als Belegdatum","2 Kästen mit Riss","2 Kartons mit Fehlmenge","8 Kartons mit je 10 Stück","78 Stück gezählt","80 Stück laut Lieferant"],"answer":[0,3,5],"criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","why":"Aus 8 Kartons zu je 10 Stück ergeben sich 80 Stück laut Beleg. 78 ist das Ergebnis der späteren Zählung. Der Beleg ist vom 10.07.","hint":"Lies die Kartonangabe zuerst als Rechenaufgabe und dann das Datum.","steps":"Halte fest, was du entscheiden oder berechnen sollst. Prüfe dann jede Aussage einzeln mit dem Hinweis.","example":"Streiche eine Aussage erst dann, wenn du zeigen kannst, welche Angabe oder Regel ihr widerspricht.","sourceRefs":["Handlungssituation","Ü1","Ü2","Ü3","Ü4"],"coreId":2,"reserveNo":2},{"id":36,"l":1,"c":4,"type":"multi","caseLabel":"LS 3.3 · Wenn Lieferungen nicht wie vereinbart erfolgen","title":"Eine Fehlmenge ausweisen","scene":"Der Beleg nennt 100 Stück. Das Lager zählt 95. Der Einkauf will den richtigen Wert im Feld „Fehlmenge zur Belegmenge“.","ask":"Welche Angaben sind für dieses Feld und seinen Rechenweg richtig?","options":["Beleg und Zählung stimmen überein.","Differenz 5 Stück","Differenz 8 Stück","Rechnung 100 − 95","Soll waren 95 Stück.","Rechnung 95 − 8"],"answer":[1,3],"criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","why":"100 minus 95 ergibt 5 fehlende Stücke. Acht ist die Zahl beschädigter Kästen und gehört in ein anderes Feld.","hint":"Fehlende Stücke wurden gar nicht gezählt.","steps":"Halte fest, was du entscheiden oder berechnen sollst. Prüfe dann jede Aussage einzeln mit dem Hinweis.","example":"Streiche eine Aussage erst dann, wenn du zeigen kannst, welche Angabe oder Regel ihr widerspricht.","sourceRefs":["Handlungssituation","Ü1","Ü2","Ü3","Ü4"],"coreId":3,"reserveNo":1},{"id":37,"l":1,"c":4,"type":"multi","caseLabel":"LS 3.3 · Wenn Lieferungen nicht wie vereinbart erfolgen","title":"Zählung mit neuer Differenz","scene":"Übungsvariante: Der Lieferbeleg nennt 64 Stück. Im Lager werden 61 gezählt. Zwei der angekommenen Kästen haben Risse.","ask":"Welche Angaben passen in die Mengenfelder der digitalen Abweichungsmeldung?","options":["Ist-Menge 63","Fehlmenge 3","Belegmenge 64","Ist-Menge 61","Fehlmenge 5","Fehlmenge 2"],"answer":[1,2,3],"criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","why":"64 minus 61 ergibt 3. Beide beschädigten Kästen gehören zur Ist-Menge. Sie sind keine weiteren fehlenden Stücke.","hint":"Trenne die Zählung von der späteren Qualitätsprüfung.","steps":"Halte fest, was du entscheiden oder berechnen sollst. Prüfe dann jede Aussage einzeln mit dem Hinweis.","example":"Streiche eine Aussage erst dann, wenn du zeigen kannst, welche Angabe oder Regel ihr widerspricht.","sourceRefs":["Handlungssituation","Ü1","Ü2","Ü3","Ü4"],"coreId":3,"reserveNo":2},{"id":38,"l":1,"c":2,"type":"multi","caseLabel":"LS 3.3 · Wenn Lieferungen nicht wie vereinbart erfolgen","title":"Drei Ebenen bei der Sichtprüfung","scene":"Für den Originalfall gibt es Beobachtungen an den Umkartons, an den Gehäusen und am Inhalt der Verbandkästen.","ask":"Welche Einträge sind korrekt?","options":["Gehäuse: fünf gerissen","Inhalt: acht Verbandkästen völlig leer","Kartons: zwei Kartons mit Druckstellen","Kartons: acht gerissen","Gehäuse: acht gerissen","Inhalt: vollständig"],"answer":[2,4,5],"criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","why":"Zwei Kartons haben Druckstellen. Acht Gehäuse sind gerissen. Der Inhalt der gelieferten Kästen ist vollständig.","hint":"Ordne erst die Gegenstände und dann die Zahlen zu.","steps":"Halte fest, was du entscheiden oder berechnen sollst. Prüfe dann jede Aussage einzeln mit dem Hinweis.","example":"Streiche eine Aussage erst dann, wenn du zeigen kannst, welche Angabe oder Regel ihr widerspricht.","sourceRefs":["Handlungssituation","Ü1","Ü2","Ü3","Ü4"],"coreId":4,"reserveNo":1},{"id":39,"l":1,"c":2,"type":"multi","caseLabel":"LS 3.3 · Wenn Lieferungen nicht wie vereinbart erfolgen","title":"Unterschiedliche Schäden melden","scene":"Übungsvariante: Ein Karton ist eingedrückt. Zwei darin liegende Gehäuse sind gerissen, überschüssige oder fehlende Teile werden bei der Inhaltsprüfung nicht festgestellt.","ask":"Welche Angaben soll der Einkauf von der Prüfung erhalten?","options":["Beobachtete Fehlmenge zwei Stück","Jeder Kasten im Karton ist gerissen.","Vollständiger Inhalt","Ein eingedrückter Karton","Zwei leere Kästen","Zwei gerissene Gehäuse"],"answer":[2,3,5],"criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","why":"Beschädigte Verpackung, gerissene Gehäuse und vollständige Inhalte sind getrennte Beobachtungen. Nur belegte Befunde gehören in die Meldung.","hint":"Ändert ein Riss an der Hülle die Zahl der gezählten Inhaltsstücke?","steps":"Halte fest, was du entscheiden oder berechnen sollst. Prüfe dann jede Aussage einzeln mit dem Hinweis.","example":"Streiche eine Aussage erst dann, wenn du zeigen kannst, welche Angabe oder Regel ihr widerspricht.","sourceRefs":["Handlungssituation","Ü1","Ü2","Ü3","Ü4"],"coreId":4,"reserveNo":2},{"id":40,"l":1,"c":3,"type":"multi","caseLabel":"LS 3.3 · Wenn Lieferungen nicht wie vereinbart erfolgen","title":"Schadensfreie Ware ermitteln","scene":"Elias hat 95 Verbandkästen gezählt. Er hält 8 sichtbar beschädigte Kästen getrennt.","ask":"Welche Zahlen zeigen die Berechnung der Ware ohne sichtbare Mängel?","options":["100 − 8","92 Stück","5 Stück","87 Stück","95 + 8","95 − 8"],"answer":[3,5],"criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","why":"Die acht beschädigten Stücke werden von den 95 gelieferten abgezogen. Es bleiben 87 ohne sichtbare Mängel.","hint":"Waren die fehlenden fünf Stücke in den 95 enthalten?","steps":"Halte fest, was du entscheiden oder berechnen sollst. Prüfe dann jede Aussage einzeln mit dem Hinweis.","example":"Streiche eine Aussage erst dann, wenn du zeigen kannst, welche Angabe oder Regel ihr widerspricht.","sourceRefs":["Handlungssituation","Ü1","Ü2","Ü3","Ü4"],"coreId":5,"reserveNo":1},{"id":41,"l":1,"c":3,"type":"multi","caseLabel":"LS 3.3 · Wenn Lieferungen nicht wie vereinbart erfolgen","title":"Verfügbarkeit bei einer neuen Zählung","scene":"Übungsvariante: Global Bike bestellt 72 Kästen. Es kommen 69 an. Davon sind 4 sichtbar beschädigt.","ask":"Welche Einträge stimmen?","options":["65 Stück sind ohne die genannten Schäden.","69 Stück sind ohne Sichtschaden.","72 Stück sind angekommen.","4 Stück fehlen.","3 Stück fehlen.","7 Stück fehlen oder sind beschädigt."],"answer":[0,4,5],"criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","why":"72 minus 69 ergibt 3 fehlende. 69 minus 4 ergibt 65 ohne sichtbare Schäden. Insgesamt sind 7 Stück fehlend oder beschädigt.","hint":"Rechne mit zwei unterschiedlichen Startwerten: bestellt und angekommen.","steps":"Halte fest, was du entscheiden oder berechnen sollst. Prüfe dann jede Aussage einzeln mit dem Hinweis.","example":"Streiche eine Aussage erst dann, wenn du zeigen kannst, welche Angabe oder Regel ihr widerspricht.","sourceRefs":["Handlungssituation","Ü1","Ü2","Ü3","Ü4"],"coreId":5,"reserveNo":2},{"id":42,"l":1,"c":1,"type":"multi","caseLabel":"LS 3.3 · Wenn Lieferungen nicht wie vereinbart erfolgen","title":"Vom Solltermin zum tatsächlichen Eingang","scene":"In der Originalübung sind als Lieferdaten der 15.06. und der 19.06. genannt.","ask":"Welche Beschriftungen gehören an die Zeitachse?","options":["19.06. tatsächlicher Eingang","15.06. tatsächlicher Eingang","16.06. Liefertag","18.06. Eingang der Lieferung","19.06. nachträglich vereinbart","15.06. vereinbart"],"answer":[0,5],"criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","why":"Der 15.06. war der vereinbarte Termin. Am 19.06. ist die Ware tatsächlich eingetroffen.","hint":"Lies die beiden Daten in der Reihenfolge Soll und Ist.","steps":"Halte fest, was du entscheiden oder berechnen sollst. Prüfe dann jede Aussage einzeln mit dem Hinweis.","example":"Streiche eine Aussage erst dann, wenn du zeigen kannst, welche Angabe oder Regel ihr widerspricht.","sourceRefs":["Handlungssituation","Ü1","Ü2","Ü3","Ü4"],"coreId":6,"reserveNo":1},{"id":43,"l":1,"c":1,"type":"multi","caseLabel":"LS 3.3 · Wenn Lieferungen nicht wie vereinbart erfolgen","title":"Eine Verspätung im Kalender abbilden","scene":"Übungsvariante: Eine Ware ist für den 07.07. vereinbart und trifft am 10.07. ein.","ask":"Welche Einträge gehören in den Prüfbericht?","options":["Soll 10.07.","Verspätung 4 Kalendertage","Verspätung 3 Kalendertage","Soll 07.07.","Ist 10.07.","Ist 07.07."],"answer":[2,3,4],"criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","why":"Vom vereinbarten 07.07. bis zur tatsächlichen Lieferung am 10.07. liegen drei Kalendertage.","hint":"Zähle den vereinbarten Tag nicht als verspäteten Tag.","steps":"Halte fest, was du entscheiden oder berechnen sollst. Prüfe dann jede Aussage einzeln mit dem Hinweis.","example":"Streiche eine Aussage erst dann, wenn du zeigen kannst, welche Angabe oder Regel ihr widerspricht.","sourceRefs":["Handlungssituation","Ü1","Ü2","Ü3","Ü4"],"coreId":6,"reserveNo":2},{"id":44,"l":1,"c":2,"type":"multi","caseLabel":"LS 3.3 · Wenn Lieferungen nicht wie vereinbart erfolgen","title":"Bezug und Belege zum Schaden","scene":"Beim Originalfall muss der Einkauf das Foto und die Feststellung zum richtigen Eingang zuordnen können.","ask":"Welche Einträge gehören in die Meldung?","options":["Nur der Aktionszeitraum des Vertriebs","Datum der Prüfung","Bestell- und Lieferscheinbezug","Behauptete Schadenssumme als Ersatz für das Foto","Name eines wartenden Kunden als einziger Lieferbezug","Foto mit erkennbaren Rissen"],"answer":[1,2,5],"criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","why":"Der Geschäftsvorgang ist über Belege und Datum zuzuordnen. Das Foto unterstützt die Beschreibung der sichtbaren Risse.","hint":"Womit findet die nächste Person genau diese Lieferung?","steps":"Halte fest, was du entscheiden oder berechnen sollst. Prüfe dann jede Aussage einzeln mit dem Hinweis.","example":"Streiche eine Aussage erst dann, wenn du zeigen kannst, welche Angabe oder Regel ihr widerspricht.","sourceRefs":["Handlungssituation","Ü1","Ü2","Ü3","Ü4"],"coreId":7,"reserveNo":1},{"id":45,"l":1,"c":2,"type":"multi","caseLabel":"LS 3.3 · Wenn Lieferungen nicht wie vereinbart erfolgen","title":"Ein Foto zuordnen","scene":"Übungsvariante: Im Einkauf kommen gleichzeitig fünf Schadensfotos aus verschiedenen Lieferungen an. Für einen Vorgang fehlen drei Stück und zwei Gehäuse sind gerissen.","ask":"Wie sicherst du einen verwertbaren Bericht zu diesem Vorgang?","options":["Prüfdatum ergänzen.","„5 fehlen“ eintragen, da beide Fehler zusammen fünf ergeben.","Fehlmenge und beschädigte Menge getrennt nennen.","Fotos dem richtigen Lieferschein zuordnen.","Fotos ungeprüft zusammen mit einem fremden Wareneingang ablegen.","Mit dem Foto belegen, dass der Lieferant schon am Vortag von allen Schäden wusste."],"answer":[0,2,3],"criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","why":"Bezug, Datum und getrennte Mengen machen die Feststellung überprüfbar. Ein Foto beweist den sichtbaren Zustand und nicht die frühere Kenntnis des Lieferanten.","hint":"Trenne Belegzuordnung und tatsächlichen Inhalt der Mitteilung.","steps":"Halte fest, was du entscheiden oder berechnen sollst. Prüfe dann jede Aussage einzeln mit dem Hinweis.","example":"Streiche eine Aussage erst dann, wenn du zeigen kannst, welche Angabe oder Regel ihr widerspricht.","sourceRefs":["Handlungssituation","Ü1","Ü2","Ü3","Ü4"],"coreId":7,"reserveNo":2},{"id":46,"l":1,"c":1,"type":"multi","caseLabel":"LS 3.3 · Wenn Lieferungen nicht wie vereinbart erfolgen","title":"Gerissene Ware im Lager","scene":"Im Originalfall sind acht gerissene Gehäuse erkannt. Bis zur Entscheidung des Einkaufs muss das Lager weiterarbeiten.","ask":"Was schützt Ware und Belege?","options":["Beweise erst sammeln, wenn die Ware verkauft ist.","Alle Kästen mit Rissen an Kunden ausgeben.","Gerissene Kästen unter den übrigen mischen.","Risse fotografieren.","Kästen mit Rissen separat halten.","Schäden aus dem Prüfbericht löschen."],"answer":[3,4],"criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","why":"Getrennte Ware wird nicht versehentlich weitergegeben. Fotos sichern den Befund für die Reklamation.","hint":"Welche Schritte kannst du vor einer Entscheidung bereits ausführen?","steps":"Halte fest, was du entscheiden oder berechnen sollst. Prüfe dann jede Aussage einzeln mit dem Hinweis.","example":"Streiche eine Aussage erst dann, wenn du zeigen kannst, welche Angabe oder Regel ihr widerspricht.","sourceRefs":["Handlungssituation","Ü1","Ü2","Ü3","Ü4"],"coreId":8,"reserveNo":1},{"id":47,"l":1,"c":1,"type":"multi","caseLabel":"LS 3.3 · Wenn Lieferungen nicht wie vereinbart erfolgen","title":"Mit der Übergabe an den Einkauf","scene":"Übungsvariante: Eine zweite Gruppe übernimmt Schicht und Lagerfläche. Zwei gerissene Kästen liegen bereits abseits der übrigen Ware.","ask":"Was gehört zur Übergabe, damit die Abweichung sicher weiterbearbeitet wird?","options":["Die Abweichung kurz im Schichtwechsel nennen und dokumentiert zugeordnet lassen.","Den Lieferbeleg ohne Kennzeichnung umschreiben.","Die zurückgehaltenen Kästen weiter eindeutig kennzeichnen.","Den dokumentierten Befund mit Bezug an den Einkauf geben.","Die Fotos nach der internen Meldung vernichten.","Die Kästen ohne Eintrag zurück in den Verkauf legen."],"answer":[0,2,3],"criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","why":"Kennzeichnung, zugeordnete Meldung und klare Übergabe verhindern Verwechslungen. Der Einkauf braucht die Belege zur weiteren Klärung.","hint":"Frage dich, was die nächste Schicht sehen und der Einkauf nachlesen kann.","steps":"Halte fest, was du entscheiden oder berechnen sollst. Prüfe dann jede Aussage einzeln mit dem Hinweis.","example":"Streiche eine Aussage erst dann, wenn du zeigen kannst, welche Angabe oder Regel ihr widerspricht.","sourceRefs":["Handlungssituation","Ü1","Ü2","Ü3","Ü4"],"coreId":8,"reserveNo":2},{"id":48,"l":1,"c":0,"type":"multi","caseLabel":"LS 3.3 · Wenn Lieferungen nicht wie vereinbart erfolgen","title":"Abweichungen an den richtigen Ort legen","scene":"Eine Lieferung kommt zu spät. In den tatsächlich gelieferten Kästen sind Gehäuse gerissen.","ask":"Welche Zuordnungen trennen die beiden Störungen richtig?","options":["Verspätung: Beschaffenheit des Gehäuses","Risse: Terminvereinbarung","Risse: automatisch ein Verzugsschaden","Risse: Zustand der gelieferten Kästen","Verspätung: immer eine Mengenabweichung","Verspätung: Zeitpunkt der Lieferung"],"answer":[3,5],"criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","why":"Die Verspätung liegt auf der Zeitachse. Risse betreffen die Beschaffenheit der Ware.","hint":"Frage: Wann kam es an, und wie war die Ware?","steps":"Halte fest, was du entscheiden oder berechnen sollst. Prüfe dann jede Aussage einzeln mit dem Hinweis.","example":"Streiche eine Aussage erst dann, wenn du zeigen kannst, welche Angabe oder Regel ihr widerspricht.","sourceRefs":["Handlungssituation","Ü1","Ü2","Ü3","Ü4"],"coreId":9,"reserveNo":1},{"id":49,"l":1,"c":0,"type":"multi","caseLabel":"LS 3.3 · Wenn Lieferungen nicht wie vereinbart erfolgen","title":"Zwei Abweichungen bei neuen Mengen","scene":"Übungsvariante: Eine Lieferung wird für Dienstag vereinbart, kommt Donnerstag und enthält 3 Stück weniger als bestellt. Die gelieferten Stücke zeigen keine sichtbaren Schäden.","ask":"Welche Feststellungen gehören in den Vergleich?","options":["Drei der eingetroffenen Stücke haben sichtbare Risse.","Eingang nach dem vereinbarten Datum.","Drei bestellte Stücke fehlen.","Die Lieferung ist pünktlich.","Die Verspätung hebt die Fehlmenge auf.","Eine Terminabweichung und eine Mengenabweichung werden getrennt notiert."],"answer":[1,2,5],"criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","why":"Donnerstag liegt nach Dienstag. Die drei fehlenden Stücke bilden eine eigene Abweichung, auch bei intakter gelieferter Ware.","hint":"Betrachte Termin und Menge unabhängig voneinander.","steps":"Halte fest, was du entscheiden oder berechnen sollst. Prüfe dann jede Aussage einzeln mit dem Hinweis.","example":"Streiche eine Aussage erst dann, wenn du zeigen kannst, welche Angabe oder Regel ihr widerspricht.","sourceRefs":["Handlungssituation","Ü1","Ü2","Ü3","Ü4"],"coreId":9,"reserveNo":2},{"id":50,"l":1,"c":0,"type":"multi","caseLabel":"LS 3.3 · Wenn Lieferungen nicht wie vereinbart erfolgen","title":"Eine Aufforderung und eine Frist","scene":"Der Einkauf formuliert: „Bitte liefern Sie die ausstehende Ware bis zu diesem neuen angemessenen Termin.“","ask":"Was enthält dieser Satz?","options":["Einen zusätzlichen Zeitraum zur Leistung","Eine Aufforderung zur fälligen Lieferung","Automatisch einen vollzogenen Rücktritt","Eine Anzeige bereits festgestellter Risse","Den Nachweis einer Schadenshöhe","Die Änderung der ursprünglich vereinbarten Bestellmenge"],"answer":[0,1],"criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","why":"Der Satz fordert zur Leistung auf und gibt zusätzliche Zeit. Er enthält keine Rüge für beschädigte Ware.","hint":"Suche das Handlungswort und den Zeitpunkt.","steps":"Halte fest, was du entscheiden oder berechnen sollst. Prüfe dann jede Aussage einzeln mit dem Hinweis.","example":"Streiche eine Aussage erst dann, wenn du zeigen kannst, welche Angabe oder Regel ihr widerspricht.","sourceRefs":["Handlungssituation","Ü1","Ü2","Ü3","Ü4"],"coreId":10,"reserveNo":1},{"id":51,"l":1,"c":0,"type":"multi","caseLabel":"LS 3.3 · Wenn Lieferungen nicht wie vereinbart erfolgen","title":"Beim festen Termin entscheiden","scene":"Übungsvariante: Ein fester Termin ist verstrichen. Global Bike will die Lieferung weiterhin und behält sich je nach Entwicklung weitere Schritte vor.","ask":"Welche Überlegungen passen?","options":["Global Bike kann zur Lieferung auffordern.","Das feste Datum ersetzt jede Mitteilung über mögliche Mängel.","Nachfrist bedeutet, die Liefermenge herabzusetzen.","Eine weitere angemessene Frist kann für einen späteren Rücktritt wichtig sein.","Für die Verzugsprüfung kann eine Mahnung aufgrund des festen Datums entbehrlich sein.","Weil die Mahnung entbehrlich sein kann, ist eine Nachfrist für jedes andere Recht entbehrlich."],"answer":[0,3,4],"criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","why":"Mahnungsregel und Nachfrist werden getrennt geprüft. Eine klare Lieferaufforderung kann trotz festem Datum sinnvoll sein.","hint":"Unterscheide Eintritt des Verzugs und spätere Rechtsentscheidung.","steps":"Halte fest, was du entscheiden oder berechnen sollst. Prüfe dann jede Aussage einzeln mit dem Hinweis.","example":"Streiche eine Aussage erst dann, wenn du zeigen kannst, welche Angabe oder Regel ihr widerspricht.","sourceRefs":["Handlungssituation","Ü1","Ü2","Ü3","Ü4"],"coreId":10,"reserveNo":2},{"id":52,"l":1,"c":2,"type":"multi","caseLabel":"LS 3.3 · Wenn Lieferungen nicht wie vereinbart erfolgen","title":"Eine klare Bitte schreiben","scene":"Der vereinbarte Termin ist vorbei. Der Einkauf braucht eine kurze Rückmeldung des Lieferanten zur noch ausstehenden Lieferung.","ask":"Welche Sätze passen?","options":["„Senden Sie auf keinen Fall noch eine Lieferinformation.“","„Bitte bestätigen Sie uns, wann die Ware eintrifft.“","„Wir bitten um kurzfristige Rückmeldung zur ausstehenden Lieferung.“","„Sie sind unzuverlässig und unfähig.“","„Sie können sich mit der Antwort bis zu unserer nächsten Bestellung Zeit lassen.“","„Wir halten fest, dass alle Kunden wegen Ihnen storniert haben.“"],"answer":[1,2],"criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","why":"Die beiden sachlichen Bitten nennen konkret, welche Information der Einkauf braucht, und vermeiden unbelegte Vorwürfe.","hint":"Welche Nachricht kann der Lieferant mit einer konkreten Angabe beantworten?","steps":"Halte fest, was du entscheiden oder berechnen sollst. Prüfe dann jede Aussage einzeln mit dem Hinweis.","example":"Streiche eine Aussage erst dann, wenn du zeigen kannst, welche Angabe oder Regel ihr widerspricht.","sourceRefs":["Handlungssituation","Ü1","Ü2","Ü3","Ü4"],"coreId":11,"reserveNo":1},{"id":53,"l":1,"c":2,"type":"multi","caseLabel":"LS 3.3 · Wenn Lieferungen nicht wie vereinbart erfolgen","title":"Sachlich auf widersprüchliche Angaben reagieren","scene":"Übungsvariante: Der Lieferant hält den Lieferschein für richtig. Im Lager fehlen nach der Zählung zwei Stück.","ask":"Welche Sätze erleichtern die weitere Abstimmung?","options":["„Bitte prüfen Sie den Vorgang anhand der angegebenen Belegnummer und melden Sie sich kurzfristig.“","„Sie haben absichtlich zwei Stück behalten.“","„Wir haben eine Pauschale festgelegt, also nehmen Sie keine Warenprüfung mehr vor.“","„Bitte teilen Sie uns mit, wann Sie die fehlenden Stücke nachliefern können.“","„Bei der Zählung haben wir zwei Stück weniger als auf dem Lieferschein festgestellt.“","„Der Lieferschein soll aus allen Unterlagen entfernt werden.“"],"answer":[0,3,4],"criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","why":"Konkreter Befund, Belegbezug und eine klare Bitte ermöglichen eine nachprüfbare Klärung. Unterstellungen oder erfundene Beträge helfen dabei nicht.","hint":"Verbinde die Aussage aus der eigenen Prüfung mit einer klaren Bitte an die andere Seite.","steps":"Halte fest, was du entscheiden oder berechnen sollst. Prüfe dann jede Aussage einzeln mit dem Hinweis.","example":"Streiche eine Aussage erst dann, wenn du zeigen kannst, welche Angabe oder Regel ihr widerspricht.","sourceRefs":["Handlungssituation","Ü1","Ü2","Ü3","Ü4"],"coreId":11,"reserveNo":2},{"id":54,"l":2,"c":0,"type":"multi","caseLabel":"LS 3.3 · Wenn Lieferungen nicht wie vereinbart erfolgen","title":"Welche Daten gelten am Stichtag?","scene":"Der Einkauf prüft den Vorgang mit Stand 16.06. Der bestätigte Termin war der 15.06., die Ware ist weiterhin nicht eingetroffen.","ask":"Welche Einträge sind für den Prüfstand richtig?","options":["„Schon acht Gehäuse mit Rissen geprüft“.","„Die Ware gilt wegen der Bestätigung als eingetroffen“.","„Beide Mengen abgestimmt und als korrekt gemeldet“.","„Lieferung fällig und noch nicht eingetroffen“.","„Nachricht zum internen Fehler liegt noch nicht vor“.","„Ein fester Liefertermin war nicht vereinbart“."],"answer":[3,4],"criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","why":"Am 16.06. steht die fällige Ware noch aus. Der Lieferant nennt seine Ursache erst am 17.06. und die Ware kommt am 19.06. an.","hint":"Vergleiche das Datum des Prüfstands mit jedem Ereignis.","steps":"Halte fest, was du entscheiden oder berechnen sollst. Prüfe dann jede Aussage einzeln mit dem Hinweis.","example":"Streiche eine Aussage erst dann, wenn du zeigen kannst, welche Angabe oder Regel ihr widerspricht.","sourceRefs":["Handlungssituation","Ü1","Ü2","Ü3","Ü4"],"coreId":12,"reserveNo":1},{"id":55,"l":2,"c":0,"type":"multi","caseLabel":"LS 3.3 · Wenn Lieferungen nicht wie vereinbart erfolgen","title":"Prüfung mit anderem Stichtag","scene":"Übungsvariante: Vertraglich vorgesehen ist der 08.09. Am 09.09. ist die Lieferung nicht da. Eine Nachricht des Lieferanten zur Ursache gibt es noch nicht.","ask":"Welche Befunde sind bereits tragfähig?","options":["Der Vertrag ist wegen eines Tages Verspätung beendet.","Eine Lieferbestätigung vom 10.09. ist bereits eingegangen.","Verantwortlichkeit ist sicher bewiesen.","Eine Mahnung ist wegen des festen Termins grundsätzlich entbehrlich.","Die Ware fehlt nach dem vereinbarten Termin.","Die Lieferung ist fällig."],"answer":[3,4,5],"criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","why":"Der bestimmte Liefertermin und die Nichtleistung stehen fest. Die Mahnung ist grundsätzlich entbehrlich. Ob die Verspätung zu vertreten ist, bleibt zu prüfen.","hint":"Prüfe Termin, Lieferstatus und Mahnung. Behandle die Ursache gesondert.","steps":"Halte fest, was du entscheiden oder berechnen sollst. Prüfe dann jede Aussage einzeln mit dem Hinweis.","example":"Streiche eine Aussage erst dann, wenn du zeigen kannst, welche Angabe oder Regel ihr widerspricht.","sourceRefs":["Handlungssituation","Ü1","Ü2","Ü3","Ü4"],"coreId":12,"reserveNo":2},{"id":56,"l":2,"c":0,"type":"multi","caseLabel":"LS 3.3 · Wenn Lieferungen nicht wie vereinbart erfolgen","title":"Das Eingeständnis für die Prüfung nutzen","scene":"Der Lieferant schreibt am 17.06., dass bei ihm ein interner Bearbeitungsfehler auftrat.","ask":"Welche Angaben darfst du daraus für die Verzugsprüfung übernehmen?","options":["Die Ursache liegt laut Nachricht in der Bearbeitung des Lieferanten.","Die Ursache wurde am 17.06. bekannt.","Die Nachricht legt den Rücktritt verbindlich fest.","Der Einkauf hat seine Bestellung nachweislich vergessen.","Die vereinnahmte Lieferung ist bereits mangelfrei.","Die Nachricht beziffert einen Verzugsschaden."],"answer":[0,1],"criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","why":"Die Aussage nennt die Ursache in der Bearbeitung des Lieferanten und den Tag der Mitteilung. Für Ankunft, Qualität und Schaden braucht ihr andere Belege.","hint":"Prüfe, welche Tatsache in der Nachricht tatsächlich genannt wird.","steps":"Halte fest, was du entscheiden oder berechnen sollst. Prüfe dann jede Aussage einzeln mit dem Hinweis.","example":"Streiche eine Aussage erst dann, wenn du zeigen kannst, welche Angabe oder Regel ihr widerspricht.","sourceRefs":["Handlungssituation","Ü1","Ü2","Ü3","Ü4"],"coreId":13,"reserveNo":1},{"id":57,"l":2,"c":0,"type":"multi","caseLabel":"LS 3.3 · Wenn Lieferungen nicht wie vereinbart erfolgen","title":"Eine Ursache nachträglich dokumentieren","scene":"Übungsvariante: Für einen anderen Liefertermin prüft das Einkaufsteam am ersten Tag nur den fehlenden Eingang. Zwei Tage später räumt der Lieferant ein, den Auftrag im eigenen Haus falsch zugeordnet zu haben.","ask":"Welche Unterschiede gehören in die Fallchronik?","options":["Die spätere Nachricht spricht für Verantwortlichkeit des Lieferanten.","Den Prüfstand des ersten Tages als fehlenden Eingang ohne bekannte Ursache dokumentieren.","Am ersten Tag war der Fehler bereits belegt.","Durch den internen Fehler steht schon die Schadenssumme fest.","Jede frühere Nachricht nachträglich mit dem Fehlerbeleg umdatieren.","Den internen Fehler mit Datum der späteren Nachricht erfassen."],"answer":[0,1,5],"criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","why":"Die Chronik trennt den frühen Prüfstand von der späteren Erklärung. Der Eingeständniszeitpunkt bleibt erkennbar und die Schadenshöhe offen.","hint":"Trenne früheren Kenntnisstand und späteren Beleg.","steps":"Halte fest, was du entscheiden oder berechnen sollst. Prüfe dann jede Aussage einzeln mit dem Hinweis.","example":"Streiche eine Aussage erst dann, wenn du zeigen kannst, welche Angabe oder Regel ihr widerspricht.","sourceRefs":["Handlungssituation","Ü1","Ü2","Ü3","Ü4"],"coreId":13,"reserveNo":2},{"id":58,"l":2,"c":1,"type":"multi","caseLabel":"LS 3.3 · Wenn Lieferungen nicht wie vereinbart erfolgen","title":"Eine erste Nachricht zur Lieferung planen","scene":"Am 16.06. braucht der Einkauf eine Rückmeldung zur noch immer ausstehenden Bestellung.","ask":"Welche Inhalte setzt du auf deine Liste?","options":["Die Nachricht des Lieferanten vom 17.06. als Anhang.","Ein ausdrücklich noch nicht ermittelter Schadensbetrag als feste Forderung.","Hinweis auf den vereinbarten Termin und dass die Ware aussteht.","Aufforderung zur Lieferung.","Anfrage, wann die Ware ankommt.","Meldung über Fotos von bereits gefundenen Rissen."],"answer":[2,3,4],"criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","why":"Eine sachliche Lieferanfrage arbeitet mit den Informationen, die bereits vorliegen. Spätere Schäden und Ursachen gehören zu späteren Arbeitsschritten.","hint":"Überlege, was am 16.06. tatsächlich vorliegt und was Global Bike jetzt braucht.","steps":"Halte fest, was du entscheiden oder berechnen sollst. Prüfe dann jede Aussage einzeln mit dem Hinweis.","example":"Streiche eine Aussage erst dann, wenn du zeigen kannst, welche Angabe oder Regel ihr widerspricht.","sourceRefs":["Handlungssituation","Ü1","Ü2","Ü3","Ü4"],"coreId":14,"reserveNo":1},{"id":59,"l":2,"c":1,"type":"multi","caseLabel":"LS 3.3 · Wenn Lieferungen nicht wie vereinbart erfolgen","title":"Die Kundenversorgung terminieren","scene":"Übungsvariante: Ein Liefertermin ist um einen Tag überschritten. Der Vertrieb will Kunden einen realistischen neuen Termin nennen. Die Ware ist noch nicht eingetroffen.","ask":"Welche Schritte bereiten die Abstimmung vor?","options":["Kunden schon eine unbestätigte Lieferung versprechen.","Eine zeitnahe, konkrete Rückmeldung des Lieferanten anfordern.","Dem Vertrieb nur belegbare Zeitangaben geben und offene Punkte benennen.","Den Vorgang ohne Rückmeldung als abgeschlossen markieren.","Abweichungen am Zustand schon vor Ankunft als Tatsache melden.","Lieferung verlangen und bei Bedarf eine angemessene Nachfrist bestimmen."],"answer":[1,2,5],"criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","why":"Eine Rückmeldung verbessert die Planung. Eine begründete Aufforderung oder Nachfrist kann helfen. Ohne Bestätigung bleiben Zeitangaben gegenüber Kunden vorläufig.","hint":"Sichere zuerst einen Lieferstatus, bevor ihr feste Zusagen macht.","steps":"Halte fest, was du entscheiden oder berechnen sollst. Prüfe dann jede Aussage einzeln mit dem Hinweis.","example":"Streiche eine Aussage erst dann, wenn du zeigen kannst, welche Angabe oder Regel ihr widerspricht.","sourceRefs":["Handlungssituation","Ü1","Ü2","Ü3","Ü4"],"coreId":14,"reserveNo":2},{"id":60,"l":2,"c":3,"type":"multi","caseLabel":"LS 3.3 · Wenn Lieferungen nicht wie vereinbart erfolgen","title":"Schadensrisiken richtig kennzeichnen","scene":"Am 19.06. kennt der Einkauf eine verspätete Lieferung und Berichte über wartende Kunden. Konkrete Mehrkosten liegen noch nicht vor.","ask":"Welche Formulierungen sind für eine interne Prüfliste genau?","options":["„Für einen Verzugsschaden Verzug und nachvollziehbaren Schaden prüfen“.","„Zusatzkosten von 500 Euro bereits bestätigt“.","„Mögliche Folgen für Kundenversorgung prüfen“.","„Schadensersatz in Höhe aller Bestellwerte sofort eintragen“.","„Konkrete Mehrkosten bisher nicht belegt“.","„Eine spätere Prüfung der Belege ist ausgeschlossen“."],"answer":[0,2,4],"criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","why":"Warten und mögliche Stornierungen sind betriebliche Risiken. Eine konkrete Geldforderung braucht Nachweise und die passende rechtliche Grundlage.","hint":"Ist die jeweilige Aussage eine Vermutung oder schon ein Beleg?","steps":"Halte fest, was du entscheiden oder berechnen sollst. Prüfe dann jede Aussage einzeln mit dem Hinweis.","example":"Streiche eine Aussage erst dann, wenn du zeigen kannst, welche Angabe oder Regel ihr widerspricht.","sourceRefs":["Handlungssituation","Ü1","Ü2","Ü3","Ü4"],"coreId":15,"reserveNo":1},{"id":61,"l":2,"c":3,"type":"multi","caseLabel":"LS 3.3 · Wenn Lieferungen nicht wie vereinbart erfolgen","title":"Eine Kostenposition aufnehmen","scene":"Übungsvariante: Global Bike behauptet nach verzögerter Lieferung 80 Euro Zusatzkosten. In der Akte ist bisher kein Beleg über diese Kosten.","ask":"Wie gehst du mit dem Betrag um?","options":["Die 80 Euro sicher als Schaden beim Lieferanten abrechnen.","Die Position als noch ungeprüft festhalten.","Die Bestellung nur wegen des eingetragenen Betrags als bezahlt ansehen.","Automatisch einen noch höheren Betrag eintragen, weil die Ware verspätet war.","Nachvollziehbare Unterlagen zur tatsächlichen Entstehung ermitteln.","Neben der Kostenposition die Verzugsprüfung separat durchführen."],"answer":[1,4,5],"criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","why":"Ein genannter Betrag ersetzt den Nachweis nicht. Zur Prüfung gehören tatsächliche Entstehung und Verzug.","hint":"Welche Voraussetzungen sind schon belegt, welche nicht?","steps":"Halte fest, was du entscheiden oder berechnen sollst. Prüfe dann jede Aussage einzeln mit dem Hinweis.","example":"Streiche eine Aussage erst dann, wenn du zeigen kannst, welche Angabe oder Regel ihr widerspricht.","sourceRefs":["Handlungssituation","Ü1","Ü2","Ü3","Ü4"],"coreId":15,"reserveNo":2},{"id":62,"l":2,"c":0,"type":"multi","caseLabel":"LS 3.3 · Wenn Lieferungen nicht wie vereinbart erfolgen","title":"Erst den Ablauf eines Rücktritts prüfen","scene":"Die Lieferung für Global Bike ist fällig und noch nicht eingetroffen. Ein fester Liefertermin ist verstrichen. Es wurde noch keine zusätzliche Frist gesetzt.","ask":"Was ist für eine Entscheidung zum Rücktritt wichtig?","options":["Ein Rücktritt ist eine andere Bezeichnung für eine Liefermahnung.","Aus der Fristüberschreitung folgt kein automatisches Vertragsende.","Das feste Kalenderdatum ersetzt jede weitere Prüfung.","Im Regelfall muss eine angemessene Nachfrist gesetzt werden und erfolglos ablaufen.","Ein Rücktritt setzt stets eine pauschale Schadenssumme voraus.","Die Liefermenge muss als Folge eines Rücktritts automatisch verdoppelt werden."],"answer":[1,3],"criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","why":"Die Überschreitung des vereinbarten Datums ist keine automatische Rückabwicklung. Im Regelfall ist eine zusätzliche angemessene Frist erforderlich.","hint":"Ordne ursprüngliche Fälligkeit und möglichen späteren Rücktritt getrennt ein.","steps":"Halte fest, was du entscheiden oder berechnen sollst. Prüfe dann jede Aussage einzeln mit dem Hinweis.","example":"Streiche eine Aussage erst dann, wenn du zeigen kannst, welche Angabe oder Regel ihr widerspricht.","sourceRefs":["Handlungssituation","Ü1","Ü2","Ü3","Ü4"],"coreId":16,"reserveNo":1},{"id":63,"l":2,"c":0,"type":"multi","caseLabel":"LS 3.3 · Wenn Lieferungen nicht wie vereinbart erfolgen","title":"Erfolglose Nachfrist auswerten","scene":"Übungsvariante: Eine fällige Lieferung fehlt trotz einer angemessenen zusätzlichen Frist. Der Einkauf will beurteilen, ob er zurücktreten kann.","ask":"Welche Aussagen sind für diese Entscheidung tragfähig?","options":["Bei jeder Nachfrist muss sich durch Rücktritt der Kaufpreis erhöhen.","Ein möglicher Rücktritt ist getrennt von einer Forderung nach Verzugsschaden zu prüfen.","Gesetzliche Voraussetzungen sind vor der Entscheidung zu prüfen.","Der Vertrag wurde schon mit der ersten Verspätung automatisch beendet.","Der erfolglose Ablauf der Nachfrist kann die Prüfung eines Rücktritts eröffnen.","Der Rücktritt ist in jedem Fall vom Nachweis eines Verschuldens abhängig."],"answer":[1,2,4],"criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","why":"Eine erfolglos abgelaufene angemessene Nachfrist ist ein entscheidendes Merkmal. Rücktritt und Schadensersatz haben unterschiedliche Voraussetzungen.","hint":"Prüfe, was vor der Entscheidung erfüllt sein muss und welche Forderung du gerade prüfst.","steps":"Halte fest, was du entscheiden oder berechnen sollst. Prüfe dann jede Aussage einzeln mit dem Hinweis.","example":"Streiche eine Aussage erst dann, wenn du zeigen kannst, welche Angabe oder Regel ihr widerspricht.","sourceRefs":["Handlungssituation","Ü1","Ü2","Ü3","Ü4"],"coreId":16,"reserveNo":2},{"id":64,"l":2,"c":1,"type":"multi","caseLabel":"LS 3.3 · Wenn Lieferungen nicht wie vereinbart erfolgen","title":"Den Empfänger der Rüge bestimmen","scene":"Elias meldet die 8 beschädigten Gehäuse und die Fehlmenge intern. Der Einkauf muss die nächste Nachricht zuordnen.","ask":"Welche Schritte gehören zur Rüge?","options":["Die Prüfung verschieben, bis Kunden die beschädigten Kästen zurückgeben.","Die Abweichungen konkret und mit Mengen beschreiben.","Erfundene Schadenssumme als einzigen Inhalt einfügen.","Nur den Vertrieb in Kopie setzen und den Lieferanten weglassen.","Auf Beleg und betroffene Lieferung Bezug nehmen.","Den Lieferanten unverzüglich anschreiben."],"answer":[1,4,5],"criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","why":"Die Rüge geht an den Lieferanten, nennt die betroffene Lieferung und beschreibt die erkannten Abweichungen zeitnah.","hint":"Eine Nachricht im eigenen Unternehmen ist eine Weitergabe, aber noch keine Lieferanteninformation.","steps":"Halte fest, was du entscheiden oder berechnen sollst. Prüfe dann jede Aussage einzeln mit dem Hinweis.","example":"Streiche eine Aussage erst dann, wenn du zeigen kannst, welche Angabe oder Regel ihr widerspricht.","sourceRefs":["Handlungssituation","Ü1","Ü2","Ü3","Ü4"],"coreId":17,"reserveNo":1},{"id":65,"l":2,"c":1,"type":"multi","caseLabel":"LS 3.3 · Wenn Lieferungen nicht wie vereinbart erfolgen","title":"Sichtbare und fehlende Stücke rügen","scene":"Übungsvariante: Von 50 bestellten Kästen kommen 47 an, darunter zwei mit gerissenem Gehäuse. Der Wareneingang hat alles gezählt und gemeldet.","ask":"Welche Angaben soll der Einkauf dem Lieferanten unverzüglich mitteilen?","options":["„Von den eingetroffenen Stücken haben zwei gerissene Gehäuse.“","„Die übrigen Stücke haben sicher einen noch nicht entdeckten Mangel.“","„Fünf Stück sind überhaupt nicht eingetroffen.“","„Der Wareneingang hat nur intern berichtet, deshalb gilt die Rüge bereits als erledigt.“","„Die festgestellten Abweichungen beziehen sich auf diese Bestellung und Lieferung.“","„Aus der Bestellung fehlen drei Stück.“"],"answer":[0,4,5],"criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","why":"50 minus 47 ergibt drei fehlende. Zwei eingetroffene Kästen sind beschädigt. Beide Abweichungen gehören mit Lieferbezug in die Rüge.","hint":"Zähle die Risse nicht als zusätzliche fehlende Stücke.","steps":"Halte fest, was du entscheiden oder berechnen sollst. Prüfe dann jede Aussage einzeln mit dem Hinweis.","example":"Streiche eine Aussage erst dann, wenn du zeigen kannst, welche Angabe oder Regel ihr widerspricht.","sourceRefs":["Handlungssituation","Ü1","Ü2","Ü3","Ü4"],"coreId":17,"reserveNo":2},{"id":66,"l":2,"c":3,"type":"multi","caseLabel":"LS 3.3 · Wenn Lieferungen nicht wie vereinbart erfolgen","title":"Passende Abhilfe für zwei Mängel","scene":"Im Originalfall fehlen fünf Kästen. Acht weitere Kästen sind angekommen, ihre Gehäuse sind allerdings gerissen.","ask":"Welche zwei Zeilen passen zu einer konkreten Forderung?","options":["„Bitte ersetzen Sie acht gar nicht gelieferte Kästen.“","„Bitte liefern Sie 13 fehlende Stücke nach.“","„Bitte ersetzen Sie die acht beschädigten Kästen.“","„Bitte liefern Sie die fünf fehlenden Kästen nach.“","„Die Risse müssen nur aus dem Lieferschein gestrichen werden.“","„Bitte senden Sie insgesamt fünf beschädigte Kästen nach.“"],"answer":[2,3],"criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","why":"Nachlieferung und Ersatz richten sich an unterschiedliche Teilmengen. Der Lieferant kann so die Abhilfe für jede Abweichung nachvollziehen.","hint":"Bestimme für jede Teilmenge zuerst, ob sie angekommen ist.","steps":"Halte fest, was du entscheiden oder berechnen sollst. Prüfe dann jede Aussage einzeln mit dem Hinweis.","example":"Streiche eine Aussage erst dann, wenn du zeigen kannst, welche Angabe oder Regel ihr widerspricht.","sourceRefs":["Handlungssituation","Ü1","Ü2","Ü3","Ü4"],"coreId":18,"reserveNo":1},{"id":67,"l":2,"c":3,"type":"multi","caseLabel":"LS 3.3 · Wenn Lieferungen nicht wie vereinbart erfolgen","title":"Nacherfüllung mit neuen Mengen rechnen","scene":"Übungsvariante: Für eine Bestellung über 75 Kästen kommen 71. Drei der angekommenen Kästen sind beschädigt.","ask":"Welche Forderungen und Prüfangaben stimmen?","options":["„Vier fehlende Stücke nachliefern“.","„Den Kaufpreis durch Umbenennen der Fehlmenge verdoppeln“.","„Drei beschädigte Stücke durch mangelfreie Stücke ersetzen“.","„Insgesamt sieben Stück fehlen oder sind beschädigt“.","„75 Kästen sind tatsächlich eingetroffen“.","„Sieben fehlende Stücke nachliefern und alle vorhandenen Stücke behalten“."],"answer":[0,2,3],"criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","why":"75 minus 71 sind vier fehlende Kästen. Drei der 71 sind beschädigt, insgesamt sind damit sieben Kästen betroffen. Ersatz und Nachlieferung bleiben getrennt.","hint":"Errechne zuerst die Fehlmenge. Übernimm die beschädigten Stücke als eigene Zahl.","steps":"Halte fest, was du entscheiden oder berechnen sollst. Prüfe dann jede Aussage einzeln mit dem Hinweis.","example":"Streiche eine Aussage erst dann, wenn du zeigen kannst, welche Angabe oder Regel ihr widerspricht.","sourceRefs":["Handlungssituation","Ü1","Ü2","Ü3","Ü4"],"coreId":18,"reserveNo":2},{"id":68,"l":2,"c":2,"type":"multi","caseLabel":"LS 3.3 · Wenn Lieferungen nicht wie vereinbart erfolgen","title":"Prüfen, ob reparierte Ware hilft","scene":"Der Lieferant bietet eine Reparatur beschädigter Verbandkästen an. Das Team braucht eine Entscheidung für die Kundenversorgung.","ask":"Was muss es vor einer Zusage wissen?","options":["Ob die E-Mail der Warenprüfung mit einem bestimmten Design geschrieben wurde.","Wann die reparierten Kästen verfügbar wären.","Ob die reparierten Gehäuse anschließend vertragsgemäß sind.","Ob der Lieferant später auf die Warenprüfung verzichten möchte.","Wem der Druck der Verpackung optisch besser gefällt.","Ob die Reparatur schon als Rücktritt vom Vertrag zählt."],"answer":[1,2],"criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","why":"Dauer und vertragsgemäßes Ergebnis bestimmen, ob Reparatur für den Bedarf geeignet ist. Das Team kann danach mit Ersatz vergleichen.","hint":"Frage nach Ergebnis und Dauer, bevor du eine Lösung als sinnvoll auswählst.","steps":"Halte fest, was du entscheiden oder berechnen sollst. Prüfe dann jede Aussage einzeln mit dem Hinweis.","example":"Streiche eine Aussage erst dann, wenn du zeigen kannst, welche Angabe oder Regel ihr widerspricht.","sourceRefs":["Handlungssituation","Ü1","Ü2","Ü3","Ü4"],"coreId":19,"reserveNo":1},{"id":69,"l":2,"c":2,"type":"multi","caseLabel":"LS 3.3 · Wenn Lieferungen nicht wie vereinbart erfolgen","title":"Zwei Angebote mit verschiedenen Terminen","scene":"Übungsvariante: Der Lieferant bietet komplette Reparatur in zwölf Tagen. Eine mangelfreie Ersatzlieferung könnte in drei Tagen verfügbar sein. Der Vertrieb benötigt die Ware möglichst bald.","ask":"Welche Punkte sollte das Team in seine begründete Entscheidung aufnehmen?","options":["Kundenbedarf beeinflusst die Wahl nie.","Die frühere Lösung beendet den Kaufvertrag automatisch.","Eine vollständige Reparatur könnte grundsätzlich Abhilfe schaffen.","Zeit bis zur Kundenversorgung ist wichtig.","Eine Reparatur ist bei beschädigter Ware immer die einzig mögliche Abhilfe.","Der frühere verfügbare Ersatz kann wirtschaftlich sinnvoll sein, wenn die Angaben zur Abhilfe stimmen."],"answer":[2,3,5],"criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","why":"Beide Wege kommen als Abhilfe in Betracht. Ein früherer verlässlicher Ersatz kann den Kundenbedarf besser bedienen, wenn Ergebnis und weitere Bedingungen passen.","hint":"Vergleiche nicht nur die Zahl der Tage, sondern auch die zugesagte Qualität.","steps":"Halte fest, was du entscheiden oder berechnen sollst. Prüfe dann jede Aussage einzeln mit dem Hinweis.","example":"Streiche eine Aussage erst dann, wenn du zeigen kannst, welche Angabe oder Regel ihr widerspricht.","sourceRefs":["Handlungssituation","Ü1","Ü2","Ü3","Ü4"],"coreId":19,"reserveNo":2},{"id":70,"l":2,"c":2,"type":"multi","caseLabel":"LS 3.3 · Wenn Lieferungen nicht wie vereinbart erfolgen","title":"An Kunden denken, ohne zu spekulieren","scene":"Nach der Originalprüfung fehlen fünf Kästen, acht sind beschädigt. Die übrigen 87 weisen nach Sichtprüfung keine Mängel auf.","ask":"Welche Angaben helfen dem Verkauf bei der Abstimmung?","options":["Der Kundenbedarf hilft bei der Entscheidung zwischen möglichen Abhilfen.","95 Stück stehen einwandfrei zum Verkauf bereit.","87 Stück sind ohne die sichtbaren Schäden vorhanden.","Alle Fehlmengen kann Global Bike ohne Termin zusagen.","Alle Kundenbestellungen müssen zwingend storniert werden.","Zeit bis zur Abhilfe der 13 betroffenen Stücke ist wichtig."],"answer":[0,2,5],"criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","why":"Verfügbare Ware kann bei der Kundenplanung berücksichtigt werden, während der Einkauf klärt, wann die fehlenden und mangelhaften Stücke ersetzt werden.","hint":"Trenne tatsächlich verfügbare Menge und erwartete Abhilfe.","steps":"Halte fest, was du entscheiden oder berechnen sollst. Prüfe dann jede Aussage einzeln mit dem Hinweis.","example":"Streiche eine Aussage erst dann, wenn du zeigen kannst, welche Angabe oder Regel ihr widerspricht.","sourceRefs":["Handlungssituation","Ü1","Ü2","Ü3","Ü4"],"coreId":20,"reserveNo":1},{"id":71,"l":2,"c":2,"type":"multi","caseLabel":"LS 3.3 · Wenn Lieferungen nicht wie vereinbart erfolgen","title":"Teilmenge für eine Aktion einplanen","scene":"Übungsvariante: Von 60 bestellten Kästen sind 17 noch nicht mangelfrei verfügbar. Für heute benötigen Kunden 40 Kästen, die übrigen Anfragen kommen später.","ask":"Welche Punkte helfen Vertrieb und Einkauf bei der Planung?","options":["Die 17 betroffenen Stücke als mangelfrei zur heutigen Ausgabe einrechnen.","Für 40 benötigte Kästen stehen rechnerisch 43 geeignete Stücke bereit, soweit die Prüfung dieses Ergebnis trägt.","Die fehlenden oder beschädigten Stücke als bereits vollständig nachgeliefert dokumentieren.","Sofort alle heutigen Bestellungen streichen, da nicht alle 60 Stück vorliegen.","Kundenbedarf und verfügbare einwandfreie Stücke getrennt festhalten.","Zeit und Kosten der Abhilfe für die späteren Kundenanfragen abwägen."],"answer":[1,4,5],"criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","why":"60 minus 17 ergibt 43 verfügbare Stücke. Der heutige Bedarf von 40 ist damit rechnerisch gedeckt. Für spätere Anfragen zählt die verlässliche Abhilfe.","hint":"Vergleiche Bedarf und verfügbare Menge, bevor du weitere Maßnahmen begründest.","steps":"Halte fest, was du entscheiden oder berechnen sollst. Prüfe dann jede Aussage einzeln mit dem Hinweis.","example":"Streiche eine Aussage erst dann, wenn du zeigen kannst, welche Angabe oder Regel ihr widerspricht.","sourceRefs":["Handlungssituation","Ü1","Ü2","Ü3","Ü4"],"coreId":20,"reserveNo":2},{"id":72,"l":2,"c":0,"type":"multi","caseLabel":"LS 3.3 · Wenn Lieferungen nicht wie vereinbart erfolgen","title":"Wirkung der Minderung verstehen","scene":"Eine Kollegin sagt nach der erfolglosen Nacherfüllung: „Mit der Minderung machen wir den ganzen Kauf rückgängig.“","ask":"Welche Aussagen helfen bei der Korrektur?","options":["Die Minderung ersetzt die beschädigte Ware automatisch.","Eine Minderung ist die Bezeichnung für die Reparatur der Ware.","Eine Minderung setzt den Kaufpreis herab.","Ein Rücktritt ist dieselbe Maßnahme wie die Minderung.","Bei einer Minderung muss der Kaufpreis in jedem Fall erhöht werden.","Der Kaufvertrag bleibt bei einer Minderung bestehen."],"answer":[2,5],"criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","why":"Minderung bedeutet Preisreduzierung bei fortbestehendem Vertrag. Eine Reparatur oder eine Rückabwicklung hat eine andere Wirkung.","hint":"Überlege, was sich am Preis ändert und was mit dem Vertrag passiert.","steps":"Halte fest, was du entscheiden oder berechnen sollst. Prüfe dann jede Aussage einzeln mit dem Hinweis.","example":"Streiche eine Aussage erst dann, wenn du zeigen kannst, welche Angabe oder Regel ihr widerspricht.","sourceRefs":["Handlungssituation","Ü1","Ü2","Ü3","Ü4"],"coreId":21,"reserveNo":1},{"id":73,"l":2,"c":0,"type":"multi","caseLabel":"LS 3.3 · Wenn Lieferungen nicht wie vereinbart erfolgen","title":"Nach erfolgloser Abhilfe unterscheiden","scene":"Übungsvariante: Eine Nacherfüllung blieb erfolglos. Das Team möchte die Ware möglicherweise behalten. Es prüft auch, ob ein Rücktritt möglich wäre.","ask":"Welche Überlegungen passen?","options":["Erfolglose Abhilfe kann weitere Rechte eröffnen, erzwingt aber keine bestimmte Wahl.","Für einen Rücktritt sind die gesetzlichen Voraussetzungen gesondert zu prüfen.","Mit einer Minderung wird die Ware automatisch repariert.","Der bloße Wunsch, Ware zu behalten, beweist den Anspruch auf eine bestimmte Summe.","Eine Minderung kann bei passenden Voraussetzungen den Preis herabsetzen, während der Vertrag bestehen bleibt.","Auch ein unerheblicher Mangel berechtigt grundsätzlich zum vollständigen Rücktritt."],"answer":[0,1,4],"criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","why":"Erst die Voraussetzungen prüfen, dann die Wirkung des gewählten Rechts bedenken. Bei einem unerheblichen Mangel ist der Rücktritt grundsätzlich ausgeschlossen.","hint":"Welches Ergebnis will das Team erreichen, und was muss es für das gewählte Recht prüfen?","steps":"Halte fest, was du entscheiden oder berechnen sollst. Prüfe dann jede Aussage einzeln mit dem Hinweis.","example":"Streiche eine Aussage erst dann, wenn du zeigen kannst, welche Angabe oder Regel ihr widerspricht.","sourceRefs":["Handlungssituation","Ü1","Ü2","Ü3","Ü4"],"coreId":21,"reserveNo":2},{"id":74,"l":2,"c":4,"type":"multi","caseLabel":"LS 3.3 · Wenn Lieferungen nicht wie vereinbart erfolgen","title":"Spätere Angaben aus dem Entwurf nehmen","scene":"Der Entwurf für den 16.06. enthält drei Sachverhalte: fällige Bestellung, ausgebliebene Lieferung und einen am 17.06. genannten internen Fehler.","ask":"Wie passt du die Nachricht für den 16.06. an?","options":["Wegen der späteren Ursache sämtliche Angaben zur Bestellung streichen.","Interne Ursache vom 17.06. streichen.","Fehlende Lieferung als damalige Tatsache nennen.","Am 16.06. schon den Wareneingang vom 19.06. bestätigen.","Später bekannt gewordene Risse ergänzen.","Bestellbezug beibehalten."],"answer":[1,2,5],"criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","why":"Am 16.06. stehen die fällige Bestellung und die ausstehende Ware fest. Spätere Angaben werden nicht vorgezogen.","hint":"Prüfe zu jeder Information, ab welchem Datum sie bekannt ist.","steps":"Halte fest, was du entscheiden oder berechnen sollst. Prüfe dann jede Aussage einzeln mit dem Hinweis.","example":"Streiche eine Aussage erst dann, wenn du zeigen kannst, welche Angabe oder Regel ihr widerspricht.","sourceRefs":["Handlungssituation","Ü1","Ü2","Ü3","Ü4"],"coreId":22,"reserveNo":1},{"id":75,"l":2,"c":4,"type":"multi","caseLabel":"LS 3.3 · Wenn Lieferungen nicht wie vereinbart erfolgen","title":"Zwei Nachrichten für andere Daten trennen","scene":"Übungsvariante: Am 04.09. ist der Termin abgelaufen und keine Ware da. Erst am 06.09. kommt sie an und bei der Prüfung werden Risse festgestellt. Du bearbeitest den Entwurf für den 04.09.","ask":"Welche Sätze gehören zu diesem Entwurf?","options":["„Unsere Nachricht bezieht sich auf die vereinbarte Bestellung.“","„Bitte teilen Sie mit, wann die Ware kommt.“","„Heute prüfen wir die Risse an den am 06.09. eingetroffenen Gehäusen.“","„Menge und Zustand bei der Ankunft am 06.09. sind bereits abschließend bestätigt.“","„Die fällige Lieferung zu unserer Bestellung ist noch nicht eingetroffen.“","„Bitte ersetzen Sie bereits die zusätzlich vermuteten fünf Kästen.“"],"answer":[0,1,4],"criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","why":"Der Entwurf für den 04.09. kennt den Termin, die Bestellung und die ausbleibende Lieferung. Die spätere Warenprüfung gehört in einen eigenen Vorgang und eine eigene Nachricht.","hint":"Beurteile die Nachricht aus Sicht des Datums in ihrer Kopfzeile.","steps":"Halte fest, was du entscheiden oder berechnen sollst. Prüfe dann jede Aussage einzeln mit dem Hinweis.","example":"Streiche eine Aussage erst dann, wenn du zeigen kannst, welche Angabe oder Regel ihr widerspricht.","sourceRefs":["Handlungssituation","Ü1","Ü2","Ü3","Ü4"],"coreId":22,"reserveNo":2},{"id":76,"l":2,"c":4,"type":"multi","caseLabel":"LS 3.3 · Wenn Lieferungen nicht wie vereinbart erfolgen","title":"Eine Mappe gegenprüfen","scene":"Die Ermittlungsmappe enthält eine Abweichungstabelle, die rechtliche Prüfung und zwei E-Mail-Entwürfe. Sie soll im Unterricht abgegeben werden.","ask":"Welche Kontrollen helfen vor der Abgabe?","options":["Prüfen, ob beide Nachrichten den passenden Prüfstand nutzen.","Die Zahlen mit der dokumentierten Zählung abgleichen.","Beide Nachrichten vor Abgabe an den Lieferanten versenden.","Belegangaben entfernen, damit sich die Seiten leichter lesen lassen.","Freigabe nur nach Blick auf die Schriftfarbe.","Maßnahmen auf rechtliche Voraussetzungen und Begründung prüfen."],"answer":[0,1,5],"criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","why":"Zahlen, Zeitpunkt, Begründung und Belege müssen zusammenpassen. Die Nachrichten sind Entwürfe für das Lernpaket.","hint":"Prüfe zuerst Inhalt und Belege. Achte dann darauf, dass beide Entwürfe lesbar sind.","steps":"Halte fest, was du entscheiden oder berechnen sollst. Prüfe dann jede Aussage einzeln mit dem Hinweis.","example":"Streiche eine Aussage erst dann, wenn du zeigen kannst, welche Angabe oder Regel ihr widerspricht.","sourceRefs":["Handlungssituation","Ü1","Ü2","Ü3","Ü4"],"coreId":23,"reserveNo":1},{"id":77,"l":2,"c":4,"type":"multi","caseLabel":"LS 3.3 · Wenn Lieferungen nicht wie vereinbart erfolgen","title":"Ein Plakat mit einem Rechenfehler","scene":"Übungsvariante: Das Erklärplakat zur Originalbestellung nennt „95 Stück mangelfrei“. Die Anlagen nennen 95 eingetroffene und acht gerissene Gehäuse. Beide E-Mail-Entwürfe liegen vor.","ask":"Welche Schritte gehören zur Selbstkontrolle?","options":["Zwei nachvollziehbare E-Mails mit den jeweiligen Daten und Bezügen beilegen.","Die 95 als Ist-Menge weiterhin im richtigen Feld dokumentieren.","Das ursprüngliche Leistungsdatum aus allen Unterlagen löschen.","Die Darstellung auf 87 Stück ohne sichtbare Mängel korrigieren.","Die Abweichung durch ein größeres Titelbild ausgleichen.","Die acht gerissenen Gehäuse aus den Entwürfen streichen, damit die Zahl 95 passt."],"answer":[0,1,3],"criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","why":"Die Ist-Menge und die Anzahl ohne sichtbare Schäden sind unterschiedliche Werte. Zahlen und E-Mails müssen mit der tatsächlichen Prüfung übereinstimmen.","hint":"Rechne angekommen minus beschädigt und prüfe anschließend beide Nachrichten.","steps":"Halte fest, was du entscheiden oder berechnen sollst. Prüfe dann jede Aussage einzeln mit dem Hinweis.","example":"Streiche eine Aussage erst dann, wenn du zeigen kannst, welche Angabe oder Regel ihr widerspricht.","sourceRefs":["Handlungssituation","Ü1","Ü2","Ü3","Ü4"],"coreId":23,"reserveNo":2}];
